                    subfilepath, is_namespace, path=additional_search_path
                )
                submodname = ".".join(modpath)
                result.append(
                    {
                        "path": subfilepath,
                        "name": submodname,
                        "isarg": False,
                        "basepath": filepath,
                        "basename": modname,
                    }
                )
    return result, errors

def get_module_and_frameid(node: nodes.NodeNG) -> tuple[str, str]:
    """Return the module name and the frame id in the module."""
    frame = node.frame(future=True)
    module, obj = "", []
    while frame:
        if isinstance(frame, Module):
            module = frame.name
        else:
            obj.append(getattr(frame, "name", "<lambda>"))
        try:
            frame = frame.parent.frame(future=True)
        except AttributeError:
            break
    obj.reverse()
    return module, ".".join(obj)

def to_xml(self):
    testcase = Junit.testcase(time="%.3f" % self.duration, **self.attrs)
    testcase.append(self.make_properties_node())
    for node in self.nodes:
        testcase.append(node)
    return testcase

def _get_global_properties_node(self):
    """Return a Junit node containing custom properties, if any.
    """
    if self.global_properties:
        return Junit.properties(
            [
                Junit.property(name=name, value=value)
                for name, value in self.global_properties
            ]
        )
    return ""

def pytest_runtest_setup(item: Item) -> None:
    item._store[skipped_by_mark_key] = False

    skipped = evaluate_skip_marks(item)
    if skipped:
        item._store[skipped_by_mark_key] = True
        skip(skipped.reason)

    if not item.config.option.runxfail:
        item._store[xfailed_key] = xfailed = evaluate_xfail_marks(item)
        if xfailed and not xfailed.run:
            xfail("[NOTRUN] " + xfailed.reason)

def evaluate_xfail_marks(item: Item) -> Optional[Xfail]:
    """Evaluate xfail marks on item, returning Xfail if triggered."""
    for mark in item.iter_markers(name="xfail"):
        run = mark.kwargs.get("run", True)
        strict = mark.kwargs.get("strict", item.config.getini("xfail_strict"))
        raises = mark.kwargs.get("raises", None)
        if "condition" not in mark.kwargs:
            conditions = mark.args
        else:
            conditions = (mark.kwargs["condition"],)

        # Unconditional.
        if not conditions:
            reason = mark.kwargs.get("reason", "")
            return Xfail(reason, run, strict, raises)

        # If any of the conditions are true.
        for condition in conditions:
            result, reason = evaluate_condition(item, mark, condition)
            if result:
                return Xfail(reason, run, strict, raises)

    return None

def evaluate_condition(item: Item, mark: Mark, condition: object) -> Tuple[bool, str]:
    """Evaluate a single skipif/xfail condition.

    If an old-style string condition is given, it is eval()'d, otherwise the
    condition is bool()'d. If this fails, an appropriately formatted pytest.fail
    is raised.

    Returns (result, reason). The reason is only relevant if the result is True.
    """
    # String condition.
    if isinstance(condition, str):
        globals_ = {
            "os": os,
            "sys": sys,
            "platform": platform,
            "config": item.config,
        }
        if hasattr(item, "obj"):
            globals_.update(item.obj.__globals__)  # type: ignore[attr-defined]
        try:
            filename = "<{} condition>".format(mark.name)
            condition_code = compile(condition, filename, "eval")
            result = eval(condition_code, globals_)
        except SyntaxError as exc:
            msglines = [
                "Error evaluating %r condition" % mark.name,
                "    " + condition,
                "    " + " " * (exc.offset or 0) + "^",
                "SyntaxError: invalid syntax",
            ]
            fail("\n".join(msglines), pytrace=False)
        except Exception as exc:
            msglines = [
                "Error evaluating %r condition" % mark.name,
                "    " + condition,
                *traceback.format_exception_only(type(exc), exc),
            ]
            fail("\n".join(msglines), pytrace=False)

    # Boolean condition.
    else:
        try:
            result = bool(condition)
        except Exception as exc:
            msglines = [
                "Error evaluating %r condition as a boolean" % mark.name,
                *traceback.format_exception_only(type(exc), exc),
            ]
            fail("\n".join(msglines), pytrace=False)

    reason = mark.kwargs.get("reason", None)
    if reason is None:
        if isinstance(condition, str):
            reason = "condition: " + condition
        else:
            # XXX better be checked at collection time
            msg = (
                "Error evaluating %r: " % mark.name
                + "you need to specify reason=STRING when using booleans as conditions."
            )
            fail(msg, pytrace=False)

    return result, reason

def add_marker(
    self, marker: Union[str, MarkDecorator], append: bool = True
) -> None:
    """dynamically add a marker object to the node.

    :type marker: ``str`` or ``pytest.mark.*``  object
    :param marker:
        ``append=True`` whether to append the marker,
        if ``False`` insert at position ``0``.
    """
    from _pytest.mark import MARK_GEN

    if isinstance(marker, MarkDecorator):
        marker_ = marker
    elif isinstance(marker, str):
        marker_ = getattr(MARK_GEN, marker)
    else:
        raise ValueError("is not a string or pytest.mark.* Marker")
    self.keywords[marker_.name] = marker_
    if append:
        self.own_markers.append(marker_.mark)
    else:
        self.own_markers.insert(0, marker_.mark)

def iter_markers(self, name: Optional[str] = None) -> Iterator[Mark]:
    """
    :param name: if given, filter the results by the name attribute

    iterate over all markers of the node
    """
    return (x[1] for x in self.iter_markers_with_node(name=name))

def _check_algorithm_metric(self):
    if self.algorithm not in ['auto', 'brute',
                              'kd_tree', 'ball_tree']:
        raise ValueError("unrecognized algorithm: '%s'" % self.algorithm)

    if self.algorithm == 'auto':
        if self.metric == 'precomputed':
            alg_check = 'brute'
        elif (callable(self.metric) or
              self.metric in VALID_METRICS['ball_tree']):
            alg_check = 'ball_tree'
        else:
            alg_check = 'brute'
    else:
        alg_check = self.algorithm

    if callable(self.metric):
        if self.algorithm == 'kd_tree':
            # callable metric is only valid for brute force and ball_tree
            raise ValueError(
                "kd_tree algorithm does not support callable metric '%s'"
                % self.metric)
    elif self.metric not in VALID_METRICS[alg_check]:
        raise ValueError("Metric '%s' not valid for algorithm '%s'"
                         % (self.metric, self.algorithm))

    if self.metric_params is not None and 'p' in self.metric_params:
        warnings.warn("Parameter p is found in metric_params. "
                      "The corresponding parameter from __init__ "
                      "is ignored.", SyntaxWarning, stacklevel=3)
        effective_p = self.metric_params['p']
    else:
        effective_p = self.p

    if self.metric in ['wminkowski', 'minkowski'] and effective_p < 1:
        raise ValueError("p must be greater than one for minkowski metric")

def _fit(self, X):
    self._check_algorithm_metric()
    if self.metric_params is None:
        self.effective_metric_params_ = {}
    else:
        self.effective_metric_params_ = self.metric_params.copy()

    effective_p = self.effective_metric_params_.get('p', self.p)
    if self.metric in ['wminkowski', 'minkowski']:
        self.effective_metric_params_['p'] = effective_p

    self.effective_metric_ = self.metric
    # For minkowski distance, use more efficient methods where available
    if self.metric == 'minkowski':
        p = self.effective_metric_params_.pop('p', 2)
        if p < 1:
            raise ValueError("p must be greater than one "
                             "for minkowski metric")
        elif p == 1:
            self.effective_metric_ = 'manhattan'
        elif p == 2:
            self.effective_metric_ = 'euclidean'
        elif p == np.inf:
            self.effective_metric_ = 'chebyshev'
        else:
            self.effective_metric_params_['p'] = p

    if isinstance(X, NeighborsBase):
        self._fit_X = X._fit_X
        self._tree = X._tree
        self._fit_method = X._fit_method
        return self

    elif isinstance(X, BallTree):
        self._fit_X = X.data
        self._tree = X
        self._fit_method = 'ball_tree'
        return self

    elif isinstance(X, KDTree):
        self._fit_X = X.data
        self._tree = X
        self._fit_method = 'kd_tree'
        return self

    X = check_array(X, accept_sparse='csr')

    n_samples = X.shape[0]
    if n_samples == 0:
        raise ValueError("n_samples must be greater than 0")

    if issparse(X):
        if self.algorithm not in ('auto', 'brute'):
            warnings.warn("cannot use tree with sparse input: "
                          "using brute force")
        if self.effective_metric_ not in VALID_METRICS_SPARSE['brute'] \
                and not callable(self.effective_metric_):

            raise ValueError("metric '%s' not valid for sparse input"
                             % self.effective_metric_)
        self._fit_X = X.copy()
        self._tree = None
        self._fit_method = 'brute'
        return self

    self._fit_method = self.algorithm
    self._fit_X = X

    if self._fit_method == 'auto':
        # A tree approach is better for small number of neighbors,
        # and KDTree is generally faster when available
        if ((self.n_neighbors is None or
             self.n_neighbors < self._fit_X.shape[0] // 2) and
                self.metric != 'precomputed'):
            if self.effective_metric_ in VALID_METRICS['kd_tree']:
                self._fit_method = 'kd_tree'
            elif (callable(self.effective_metric_) or
                    self.effective_metric_ in VALID_METRICS['ball_tree']):
                self._fit_method = 'ball_tree'
            else:
                self._fit_method = 'brute'
        else:
            self._fit_method = 'brute'

    if self._fit_method == 'ball_tree':
        self._tree = BallTree(X, self.leaf_size,
                              metric=self.effective_metric_,
                              **self.effective_metric_params_)
    elif self._fit_method == 'kd_tree':
        self._tree = KDTree(X, self.leaf_size,
                            metric=self.effective_metric_,
                            **self.effective_metric_params_)
    elif self._fit_method == 'brute':
        self._tree = None
    else:
        raise ValueError("algorithm = '%s' not recognized"
                         % self.algorithm)

    if self.n_neighbors is not None:
        if self.n_neighbors <= 0:
            raise ValueError(
                "Expected n_neighbors > 0. Got %d" %
                self.n_neighbors
            )

    return self

def _pairwise(self):
    # For cross-validation routines to split data correctly
    return self.metric == 'precomputed'

def _check_weights(weights):
    """Check to make sure weights are valid"""
    if weights in (None, 'uniform', 'distance'):
        return weights
    elif callable(weights):
        return weights
    else:
        raise ValueError("weights not recognized: should be 'uniform', "
                         "'distance', or a callable function")

def _get_weights(dist, weights):
    """Get the weights from an array of distances and a parameter ``weights``

    Parameters
    ===========
    dist : ndarray
        The input distances
    weights : {'uniform', 'distance' or a callable}
        The kind of weighting used

    Returns
    ========
    weights_arr : array of the same shape as ``dist``
        if ``weights == 'uniform'``, then returns None
    """
    if weights in (None, 'uniform'):
        return None
    elif weights == 'distance':
        # if user attempts to classify a point that was zero distance from one
        # or more training points, those training points are weighted as 1.0
        # and the other points as 0.0
        if dist.dtype is np.dtype(object):
            for point_dist_i, point_dist in enumerate(dist):
                # check if point_dist is iterable
                # (ex: RadiusNeighborClassifier.predict may set an element of
                # dist to 1e-6 to represent an 'outlier')
                if hasattr(point_dist, '__contains__') and 0. in point_dist:
                    dist[point_dist_i] = point_dist == 0.
                else:
                    dist[point_dist_i] = 1. / point_dist
        else:
            with np.errstate(divide='ignore'):
                dist = 1. / dist
            inf_mask = np.isinf(dist)
            inf_row = np.any(inf_mask, axis=1)
            dist[inf_row] = inf_mask[inf_row]
        return dist
    elif callable(weights):
        return weights(dist)
    else:
        raise ValueError("weights not recognized: should be 'uniform', "
                         "'distance', or a callable function")

def _compute_mi(x, y, x_discrete, y_discrete, n_neighbors=3):
    """Compute mutual information between two variables.

    This is a simple wrapper which selects a proper function to call based on
    whether `x` and `y` are discrete or not.
    """
    if x_discrete and y_discrete:
        return mutual_info_score(x, y)
    elif x_discrete and not y_discrete:
        return _compute_mi_cd(y, x, n_neighbors)
    elif not x_discrete and y_discrete:
        return _compute_mi_cd(x, y, n_neighbors)
    else:
        return _compute_mi_cc(x, y, n_neighbors)

def _compute_mi(x, y, x_discrete, y_discrete, n_neighbors=3):
    """Compute mutual information between two variables.

    This is a simple wrapper which selects a proper function to call based on
    whether `x` and `y` are discrete or not.
    """
    if x_discrete and y_discrete:
        return mutual_info_score(x, y)
    elif x_discrete and not y_discrete:
        return _compute_mi_cd(y, x, n_neighbors)
    elif not x_discrete and y_discrete:
        return _compute_mi_cd(x, y, n_neighbors)
    else:
        return _compute_mi_cc(x, y, n_neighbors)

def process_documenter_options(documenter: Type[Documenter], config: Config, options: Dict
                               ) -> Options:
    """Recognize options of Documenter from user input."""
    for name in AUTODOC_DEFAULT_OPTIONS:
        if name not in documenter.option_spec:
            continue
        else:
            negated = options.pop('no-' + name, True) is None
            if name in config.autodoc_default_options and not negated:
                if name in options and isinstance(config.autodoc_default_options[name], str):
                    # take value from options if present or extend it
                    # with autodoc_default_options if necessary
                    if name in AUTODOC_EXTENDABLE_OPTIONS:
                        if options[name] is not None and options[name].startswith('+'):
                            options[name] = ','.join([config.autodoc_default_options[name],
                                                      options[name][1:]])
                else:
                    options[name] = config.autodoc_default_options[name]

            elif options.get(name) is not None:
                # remove '+' from option argument if there's nothing to merge it with
                options[name] = options[name].lstrip('+')

    return Options(assemble_option_dict(options.items(), documenter.option_spec))

def get_object_members(self, want_all: bool) -> Tuple[bool, ObjectMembers]:
    members = get_class_members(self.object, self.objpath, self.get_attr)
    if not want_all:
        if not self.options.members:
            return False, []  # type: ignore
        # specific members given
        selected = []
        for name in self.options.members:  # type: str
            if name in members:
                selected.append(members[name])
            else:
                logger.warning(__('missing attribute %s in object %s') %
                               (name, self.fullname), type='autodoc')
        return False, selected
    elif self.options.inherited_members:
        return False, list(members.values())
    else:
        return False, [m for m in members.values() if m.class_ == self.object]

def inherited_members_option(arg: Any) -> Union[object, Set[str]]:
    """Used to convert the :members: option to auto directives."""
    if arg in (None, True):
        return 'object'
    else:
        return arg

def is_filtered_inherited_member(name: str, obj: Any) -> bool:
    if inspect.isclass(self.object):
        for cls in self.object.__mro__:
            if cls.__name__ == self.options.inherited_members and cls != self.object:
                # given member is a member of specified *super class*
                return True
            elif name in cls.__dict__:
                return False
            elif name in self.get_attr(cls, '__annotations__', {}):
                return False
            elif isinstance(obj, ObjectMember) and obj.class_ is cls:
                return False

    return False

def get_class_members(subject: Any, objpath: List[str], attrgetter: Callable
                      ) -> Dict[str, "ObjectMember"]:
    """Get members and attributes of target class."""
    from sphinx.ext.autodoc import INSTANCEATTR, ObjectMember

    # the members directly defined in the class
    obj_dict = attrgetter(subject, '__dict__', {})

    members: Dict[str, ObjectMember] = {}

    # enum members
    if isenumclass(subject):
        for name, value in subject.__members__.items():
            if name not in members:
                members[name] = ObjectMember(name, value, class_=subject)

        superclass = subject.__mro__[1]
        for name in obj_dict:
            if name not in superclass.__dict__:
                value = safe_getattr(subject, name)
                members[name] = ObjectMember(name, value, class_=subject)

    # members in __slots__
    try:
        __slots__ = getslots(subject)
        if __slots__:
            from sphinx.ext.autodoc import SLOTSATTR

            for name, docstring in __slots__.items():
                members[name] = ObjectMember(name, SLOTSATTR, class_=subject,
                                             docstring=docstring)
    except (TypeError, ValueError):
        pass

    # other members
    for name in dir(subject):
        try:
            value = attrgetter(subject, name)
            if ismock(value):
                value = undecorate(value)

            unmangled = unmangle(subject, name)
            if unmangled and unmangled not in members:
                if name in obj_dict:
                    members[unmangled] = ObjectMember(unmangled, value, class_=subject)
                else:
                    members[unmangled] = ObjectMember(unmangled, value)
        except AttributeError:
            continue

    try:
        for cls in getmro(subject):
            try:
                modname = safe_getattr(cls, '__module__')
                qualname = safe_getattr(cls, '__qualname__')
                analyzer = ModuleAnalyzer.for_module(modname)
                analyzer.analyze()
            except AttributeError:
                qualname = None
                analyzer = None
            except PycodeError:
                analyzer = None

            # annotation only member (ex. attr: int)
            for name in getannotations(cls):
                name = unmangle(cls, name)
                if name and name not in members:
                    if analyzer and (qualname, name) in analyzer.attr_docs:
                        docstring = '\n'.join(analyzer.attr_docs[qualname, name])
                    else:
                        docstring = None

                    members[name] = ObjectMember(name, INSTANCEATTR, class_=cls,
                                                 docstring=docstring)

            # append instance attributes (cf. self.attr1) if analyzer knows
            if analyzer:
                for (ns, name), docstring in analyzer.attr_docs.items():
                    if ns == qualname and name not in members:
                        members[name] = ObjectMember(name, INSTANCEATTR, class_=cls,
                                                     docstring='\n'.join(docstring))
    except AttributeError:
        pass

    return members

def getmro(obj: Any) -> Tuple[Type, ...]:
    """Get __mro__ from given *obj* safely."""
    __mro__ = safe_getattr(obj, '__mro__', None)
    if isinstance(__mro__, tuple):
        return __mro__
    else:
        return tuple()

def getorigbases(obj: Any) -> Optional[Tuple[Any, ...]]:
    """Get __orig_bases__ from *obj* safely."""
    if not inspect.isclass(obj):
        return None

    # Get __orig_bases__ from obj.__dict__ to avoid accessing the parent's __orig_bases__.
    # refs: https://github.com/sphinx-doc/sphinx/issues/9607
    __dict__ = safe_getattr(obj, '__dict__', {})
    __orig_bases__ = __dict__.get('__orig_bases__')
    if isinstance(__orig_bases__, tuple) and len(__orig_bases__) > 0:
        return __orig_bases__
    else:
        return None

def import_module(modname: str, warningiserror: bool = False) -> Any:
    """
    Call importlib.import_module(modname), convert exceptions to ImportError
    """
    try:
        with warnings.catch_warnings():
            warnings.filterwarnings("ignore", category=ImportWarning)
            with logging.skip_warningiserror(not warningiserror):
                return importlib.import_module(modname)
    except BaseException as exc:
        # Importing modules may cause any side effects, including
        # SystemExit, so we need to catch all errors.
        raise ImportError(exc, traceback.format_exc()) from exc

def import_object(modname: str, objpath: List[str], objtype: str = '',
                  attrgetter: Callable[[Any, str], Any] = safe_getattr,
                  warningiserror: bool = False) -> Any:
    if objpath:
        logger.debug('[autodoc] from %s import %s', modname, '.'.join(objpath))
    else:
        logger.debug('[autodoc] import %s', modname)

    try:
        module = None
        exc_on_importing = None
        objpath = list(objpath)
        while module is None:
            try:
                module = import_module(modname, warningiserror=warningiserror)
                logger.debug('[autodoc] import %s => %r', modname, module)
            except ImportError as exc:
                logger.debug('[autodoc] import %s => failed', modname)
                exc_on_importing = exc
                if '.' in modname:
                    # retry with parent module
                    modname, name = modname.rsplit('.', 1)
                    objpath.insert(0, name)
                else:
                    raise

        obj = module
        parent = None
        object_name = None
        for attrname in objpath:
            parent = obj
            logger.debug('[autodoc] getattr(_, %r)', attrname)
            mangled_name = mangle(obj, attrname)
            obj = attrgetter(obj, mangled_name)

            try:
                logger.debug('[autodoc] => %r', obj)
            except TypeError:
                # fallback of failure on logging for broken object
                # refs: https://github.com/sphinx-doc/sphinx/issues/9095
                logger.debug('[autodoc] => %r', (obj,))

            object_name = attrname
        return [module, parent, object_name, obj]
    except (AttributeError, ImportError) as exc:
        if isinstance(exc, AttributeError) and exc_on_importing:
            # restore ImportError
            exc = exc_on_importing

        if objpath:
            errmsg = ('autodoc: failed to import %s %r from module %r' %
                      (objtype, '.'.join(objpath), modname))
        else:
            errmsg = 'autodoc: failed to import %s %r' % (objtype, modname)

        if isinstance(exc, ImportError):
            # import_module() raises ImportError having real exception obj and
            # traceback
            real_exc, traceback_msg = exc.args
            if isinstance(real_exc, SystemExit):
                errmsg += ('; the module executes module level statement '
                           'and it might call sys.exit().')
            elif isinstance(real_exc, ImportError) and real_exc.args:
                errmsg += '; the following exception was raised:\n%s' % real_exc.args[0]
            else:
                errmsg += '; the following exception was raised:\n%s' % traceback_msg
        else:
            errmsg += '; the following exception was raised:\n%s' % traceback.format_exc()

        logger.debug(errmsg)
        raise ImportError(errmsg) from exc

def merge_typehints(app: Sphinx, domain: str, objtype: str, contentnode: Element) -> None:
    if domain != 'py':
        return
    if app.config.autodoc_typehints != 'description':
        return
    if objtype == 'class' and app.config.autoclass_content not in ('init', 'both'):
        return

    try:
        signature = cast(addnodes.desc_signature, contentnode.parent[0])
        if signature['module']:
            fullname = '.'.join([signature['module'], signature['fullname']])
        else:
            fullname = signature['fullname']
    except KeyError:
        # signature node does not have valid context info for the target object
        return

    annotations = app.env.temp_data.get('annotations', {})
    if annotations.get(fullname, {}):
        field_lists = [n for n in contentnode if isinstance(n, nodes.field_list)]
        if field_lists == []:
            field_list = insert_field_list(contentnode)
            field_lists.append(field_list)

        for field_list in field_lists:
            modify_field_list(field_list, annotations[fullname])

def format_signature(self, **kwargs: Any) -> str:
    sigs = []
    if self.analyzer and '.'.join(self.objpath) in self.analyzer.overloads:
        # Use signatures for overloaded functions instead of the implementation function.
        overloaded = True
    else:
        overloaded = False
        sig = super().format_signature(**kwargs)
        sigs.append(sig)

    if inspect.is_singledispatch_function(self.object):
        # append signature of singledispatch'ed functions
        for typ, func in self.object.registry.items():
            if typ is object:
                pass  # default implementation. skipped.
            else:
                self.annotate_to_first_argument(func, typ)

                documenter = FunctionDocumenter(self.directive, '')
                documenter.object = func
                documenter.objpath = [None]
                sigs.append(documenter.format_signature())
    if overloaded:
        __globals__ = safe_getattr(self.object, '__globals__', {})
        for overload in self.analyzer.overloads.get('.'.join(self.objpath)):
            overload = evaluate_signature(overload, __globals__,
                                          self.env.config.autodoc_type_aliases)

            sig = stringify_signature(overload, **kwargs)
            sigs.append(sig)

    return "\n".join(sigs)

def get_overloaded_signatures(self) -> List[Signature]:
    if self._signature_class and self._signature_method_name:
        for cls in self._signature_class.__mro__:
            try:
                analyzer = ModuleAnalyzer.for_module(cls.__module__)
                analyzer.parse()
                qualname = '.'.join([cls.__qualname__, self._signature_method_name])
                if qualname in analyzer.overloads:
                    return analyzer.overloads.get(qualname)
            except PycodeError:
                pass

    return []

def _getannotations(obj: Any) -> Mapping[str, Any]:
    """Get __annotations__ from given *obj* safely."""
    __annotations__ = safe_getattr(obj, '__annotations__', None)
    if isinstance(__annotations__, Mapping):
        return __annotations__
    else:
        return {}

def record_typehints(app: Sphinx, objtype: str, name: str, obj: Any,
                     options: Dict, args: str, retann: str) -> None:
    """Record type hints to env object."""
    try:
        if callable(obj):
            annotations = app.env.temp_data.setdefault('annotations', {})
            annotation = annotations.setdefault(name, OrderedDict())
            sig = inspect.signature(obj)
            for param in sig.parameters.values():
                if param.annotation is not param.empty:
                    annotation[param.name] = typing.stringify(param.annotation)
            if sig.return_annotation is not sig.empty:
                annotation['return'] = typing.stringify(sig.return_annotation)
    except (TypeError, ValueError):
        pass

def insert_field_list(node: Element) -> nodes.field_list:
    field_list = nodes.field_list()
    desc = [n for n in node if isinstance(n, addnodes.desc)]
    if desc:
        # insert just before sub object descriptions (ex. methods, nested classes, etc.)
        index = node.index(desc[0])
        node.insert(index - 1, [field_list])
    else:
        node += field_list

    return field_list

def modify_field_list(node: nodes.field_list, annotations: Dict[str, str]) -> None:
    arguments = {}  # type: Dict[str, Dict[str, bool]]
    fields = cast(Iterable[nodes.field], node)
    for field in fields:
        field_name = field[0].astext()
        parts = re.split(' +', field_name)
        if parts[0] == 'param':
            if len(parts) == 2:
                # :param xxx:
                arg = arguments.setdefault(parts[1], {})
                arg['param'] = True
            elif len(parts) > 2:
                # :param xxx yyy:
                name = ' '.join(parts[2:])
                arg = arguments.setdefault(name, {})
                arg['param'] = True
                arg['type'] = True
        elif parts[0] == 'type':
            name = ' '.join(parts[1:])
            arg = arguments.setdefault(name, {})
            arg['type'] = True
        elif parts[0] == 'rtype':
            arguments['return'] = {'type': True}

    for name, annotation in annotations.items():
        if name == 'return':
            continue

        arg = arguments.get(name, {})
        if not arg.get('type'):
            field = nodes.field()
            field += nodes.field_name('', 'type ' + name)
            field += nodes.field_body('', nodes.paragraph('', annotation))
            node += field
        if not arg.get('param'):
            field = nodes.field()
            field += nodes.field_name('', 'param ' + name)
            field += nodes.field_body('', nodes.paragraph('', ''))
            node += field

    if 'return' in annotations and 'return' not in arguments:
        field = nodes.field()
        field += nodes.field_name('', 'rtype')
        field += nodes.field_body('', nodes.paragraph('', annotation))
        node += field

def annotate_to_first_argument(self, func: Callable, typ: Type) -> None:
    """Annotate type hint to the first argument of function if needed."""
    try:
        sig = inspect.signature(func, type_aliases=self.env.config.autodoc_type_aliases)
    except TypeError as exc:
        logger.warning(__("Failed to get a function signature for %s: %s"),
                       self.fullname, exc)
        return
    except ValueError:
        return

    if len(sig.parameters) == 0:
        return

    params = list(sig.parameters.values())
    if params[0].annotation is Parameter.empty:
        params[0] = params[0].replace(annotation=typ)
        try:
            func.__signature__ = sig.replace(parameters=params)  # type: ignore
        except TypeError:
            # failed to update signature (ex. built-in or extension types)
            return

def best_origin(a, b, lineseg, expr):
    """Helper method for polytope_integrate.
    Returns a point on the lineseg whose vector inner product with the
    divergence of `expr` yields an expression with the least maximum
    total power.
    Parameters
    ==========
    a : Hyperplane parameter denoting direction.
    b : Hyperplane parameter denoting distance.
    lineseg : Line segment on which to find the origin.
    expr : The expression which determines the best point.
    Algorithm(currently works only for 2D use case)
    ===============================================
    1 > Firstly, check for edge cases. Here that would refer to vertical
        or horizontal lines.

    2 > If input expression is a polynomial containing more than one generator
        then find out the total power of each of the generators.

        x**2 + 3 + x*y + x**4*y**5 ---> {x: 7, y: 6}

        If expression is a constant value then pick the first boundary point
        of the line segment.

    3 > First check if a point exists on the line segment where the value of
        the highest power generator becomes 0. If not check if the value of
        the next highest becomes 0. If none becomes 0 within line segment
        constraints then pick the first boundary point of the line segement.
        Actually, any point lying on the segment can be picked as best origin
        in the last case.
    Examples
    ========
    >>> from sympy.integrals.intpoly import best_origin
    >>> from sympy.abc import x, y
    >>> from sympy.geometry.line import Segment2D
    >>> from sympy.geometry.point import Point
    >>> l = Segment2D(Point(0, 3), Point(1, 1))
    >>> expr = x**3*y**7
    >>> best_origin((2, 1), 3, l, expr)
    (0, 3.0)
    """
    a1, b1 = lineseg.points[0]
    def x_axis_cut(ls):
        """Returns the point where the input line segment
        intersects the x-axis.
        Parameters:
        ===========
        ls : Line segment
        """
        p, q = ls.points
        if p.y == S.Zero:
            return tuple(p)
        elif q.y == S.Zero:
            return tuple(q)
        elif p.y/q.y < S.Zero:
            return p.y * (p.x - q.x)/(q.y - p.y) + p.x, S.Zero
        else:
            return ()

    def y_axis_cut(ls):
        """Returns the point where the input line segment
        intersects the y-axis.
        Parameters:
        ===========
        ls : Line segment
        """
        p, q = ls.points
        if p.x == S.Zero:
            return tuple(p)
        elif q.x == S.Zero:
            return tuple(q)
        elif p.x/q.x < S.Zero:
            return S.Zero, p.x * (p.y - q.y)/(q.x - p.x) + p.y
        else:
            return ()

    gens = (x, y)
    power_gens = {}

    for i in gens:
        power_gens[i] = S.Zero

    if len(gens) > 1:
        # Special case for vertical and horizontal lines
        if len(gens) == 2:
            if a[0] == S.Zero:
                if y_axis_cut(lineseg):
                    return S.Zero, b/a[1]
                else:
                    return a1, b1
            elif a[1] == S.Zero:
                if x_axis_cut(lineseg):
                    return b/a[0], S.Zero
                else:
                    return a1, b1

        if isinstance(expr, Expr):  # Find the sum total of power of each
            if expr.is_Add:         # generator and store in a dictionary.
                for monomial in expr.args:
                    if monomial.is_Pow:
                        if monomial.args[0] in gens:
                            power_gens[monomial.args[0]] += monomial.args[1]
                    else:
                        for univariate in monomial.args:
                            term_type = len(univariate.args)
                            if term_type == 0 and univariate in gens:
                                power_gens[univariate] += 1
                            elif term_type == 2 and univariate.args[0] in gens:
                                power_gens[univariate.args[0]] +=\
                                           univariate.args[1]
            elif expr.is_Mul:
                for term in expr.args:
                    term_type = len(term.args)
                    if term_type == 0 and term in gens:
                        power_gens[term] += 1
                    elif term_type == 2 and term.args[0] in gens:
                        power_gens[term.args[0]] += term.args[1]
            elif expr.is_Pow:
                power_gens[expr.args[0]] = expr.args[1]
            elif expr.is_Symbol:
                power_gens[expr] += 1
        else:  # If `expr` is a constant take first vertex of the line segment.
            return a1, b1

        #  TODO : This part is quite hacky. Should be made more robust with
        #  TODO : respect to symbol names and scalable w.r.t higher dimensions.
        power_gens = sorted(power_gens.items(), key=lambda k: str(k[0]))
        if power_gens[0][1] >= power_gens[1][1]:
            if y_axis_cut(lineseg):
                x0 = (S.Zero, b / a[1])
            elif x_axis_cut(lineseg):
                x0 = (b / a[0], S.Zero)
            else:
                x0 = (a1, b1)
        else:
            if x_axis_cut(lineseg):
                x0 = (b/a[0], S.Zero)
            elif y_axis_cut(lineseg):
                x0 = (S.Zero, b/a[1])
            else:
                x0 = (a1, b1)
    else:
        x0 = (b/a[0])
    return x0

def clockwise_sort(poly):
    """Returns the same polygon with points sorted in clockwise order.

    Note that it's necessary for input points to be sorted in some order
    (clockwise or anti-clockwise) for the algorithm to work. As a convention
    algorithm has been implemented keeping clockwise orientation in mind.

    Parameters
    ==========
    poly: 2-Polytope

    Examples
    ========
    >>> from sympy.integrals.intpoly import clockwise_sort
    >>> from sympy.geometry.point import Point
    >>> from sympy.geometry.polygon import Polygon
    >>> clockwise_sort(Polygon(Point(0, 0), Point(1, 0), Point(1, 1)))
    Triangle(Point2D(1, 1), Point2D(1, 0), Point2D(0, 0))

    """
    n = len(poly.vertices)
    vertices = list(poly.vertices)
    center = Point(sum(map(lambda vertex: vertex.x, poly.vertices)) / n,
                   sum(map(lambda vertex: vertex.y, poly.vertices)) / n)

    def compareTo(a, b):
        if a.x - center.x >= S.Zero and b.x - center.x < S.Zero:
            return S(-1)
        elif a.x - center.x < S.Zero and b.x - center.x >= S.Zero:
            return S(1)
        elif a.x - center.x == S.Zero and b.x - center.x == S.Zero:
            if a.y - center.y >= S.Zero or b.y - center.y >= S.Zero:
                return S(-1) if a.y > b.y else S(1)
            return S(-1) if b.y > a.y else S(1)

        det = (a.x - center.x) * (b.y - center.y) -\
              (b.x - center.x) * (a.y - center.y)
        if det < S.Zero:
            return S(-1)
        elif det > S.Zero:
            return S(1)

        first = (a.x - center.x) * (a.x - center.x) +\
                (a.y - center.y) * (a.y - center.y)
        second = (b.x - center.x) * (b.x - center.x) +\
                 (b.y - center.y) * (b.y - center.y)
        return S(-1) if first > second else S(1)

    return Polygon(*sorted(vertices, key=cmp_to_key(compareTo)))

def decompose(expr, separate=False):
    """Decomposes an input polynomial into homogeneous ones of
    smaller or equal degree.
    Returns a dictionary with keys as the degree of the smaller
    constituting polynomials. Values are the constituting polynomials.
    Parameters
    ==========
    expr : Polynomial(SymPy expression)

    Optional Parameters :

    separate : If True then simply return a list of the constituent monomials
               If not then break up the polynomial into constituent homogeneous
               polynomials.
    Examples
    ========
    >>> from sympy.abc import x, y
    >>> from sympy.integrals.intpoly import decompose
    >>> decompose(x**2 + x*y + x + y + x**3*y**2 + y**5)
    {1: x + y, 2: x**2 + x*y, 5: x**3*y**2 + y**5}
    >>> decompose(x**2 + x*y + x + y + x**3*y**2 + y**5, True)
    [x, y, x**2, y**5, x*y, x**3*y**2]
    """
    expr = S(expr)
    poly_dict = {}

    if isinstance(expr, Expr) and not expr.is_number:
        if expr.is_Symbol:
            poly_dict[1] = expr
        elif expr.is_Add:
            symbols = expr.atoms(Symbol)
            degrees = [(sum(degree_list(monom, *symbols)), monom)
                       for monom in expr.args]
            if separate:
                return [monom[1] for monom in degrees]
            else:
                for monom in degrees:
                    degree, term = monom
                    if poly_dict.get(degree):
                        poly_dict[degree] += term
                    else:
                        poly_dict[degree] = term
        elif expr.is_Pow:
            _, degree = expr.args
            poly_dict[degree] = expr
        else:  # Now expr can only be of `Mul` type
            degree = 0
            for term in expr.args:
                term_type = len(term.args)
                if term_type == 0 and term.is_Symbol:
                    degree += 1
                elif term_type == 2:
                    degree += term.args[1]
            poly_dict[degree] = expr
    else:
        poly_dict[0] = expr

    if separate:
        return list(poly_dict.values())
    return poly_dict

def _as_ordered_terms(self, expr, order=None):
    """A compatibility function for ordering terms in Add. """
    order = order or self.order

    if order == 'old':
        return sorted(Add.make_args(expr), key=cmp_to_key(Basic._compare_pretty))
    else:
        return expr.as_ordered_terms(order=order)

def _print_Poly(self, expr):
    ATOM_PREC = PRECEDENCE["Atom"] - 1
    terms, gens = [], [ self.parenthesize(s, ATOM_PREC) for s in expr.gens ]

    for monom, coeff in expr.terms():
        s_monom = []

        for i, exp in enumerate(monom):
            if exp > 0:
                if exp == 1:
                    s_monom.append(gens[i])
                else:
                    s_monom.append(gens[i] + "**%d" % exp)

        s_monom = "*".join(s_monom)

        if coeff.is_Add:
            if s_monom:
                s_coeff = "(" + self._print(coeff) + ")"
            else:
                s_coeff = self._print(coeff)
        else:
            if s_monom:
                if coeff is S.One:
                    terms.extend(['+', s_monom])
                    continue

                if coeff is S.NegativeOne:
                    terms.extend(['-', s_monom])
                    continue

            s_coeff = self._print(coeff)

        if not s_monom:
            s_term = s_coeff
        else:
            s_term = s_coeff + "*" + s_monom

        if s_term.startswith('-'):
            terms.extend(['-', s_term[1:]])
        else:
            terms.extend(['+', s_term])

    if terms[0] in ['-', '+']:
        modifier = terms.pop(0)

        if modifier == '-':
            terms[0] = '-' + terms[0]

    format = expr.__class__.__name__ + "(%s, %s"

    from sympy.polys.polyerrors import PolynomialError

    try:
        format += ", modulus=%s" % expr.get_modulus()
    except PolynomialError:
        format += ", domain='%s'" % expr.get_domain()

    format += ")"

    for index, item in enumerate(gens):
        if len(item) > 2 and (item[:1] == "(" and item[len(item) - 1:] == ")"):
            gens[index] = item[1:len(item) - 1]

    return format % (' '.join(terms), ', '.join(gens))

def doprint(self, expr):
    tex = Printer.doprint(self, expr)

    if self._settings['mode'] == 'plain':
        return tex
    elif self._settings['mode'] == 'inline':
        return r"$%s$" % tex
    elif self._settings['itex']:
        return r"$$%s$$" % tex
    else:
        env_str = self._settings['mode']
        return r"\begin{%s}%s\end{%s}" % (env_str, tex, env_str)

def _print_Add(self, expr, order=None):
    if self.order == 'none':
        terms = list(expr.args)
    else:
        terms = self._as_ordered_terms(expr, order=order)

    tex = ""
    for i, term in enumerate(terms):
        if i == 0:
            pass
        elif _coeff_isneg(term):
            tex += " - "
            term = -term
        else:
            tex += " + "
        term_tex = self._print(term)
        if self._needs_add_brackets(term):
            term_tex = r"\left(%s\right)" % term_tex
        tex += term_tex

    return tex

def __new__(cls, lhs, rhs=0, **options):
    from sympy.core.add import Add
    from sympy.core.logic import fuzzy_bool
    from sympy.core.expr import _n2
    from sympy.simplify.simplify import clear_coefficients

    lhs = _sympify(lhs)
    rhs = _sympify(rhs)

    evaluate = options.pop('evaluate', global_evaluate[0])

    if evaluate:
        # If one expression has an _eval_Eq, return its results.
        if hasattr(lhs, '_eval_Eq'):
            r = lhs._eval_Eq(rhs)
            if r is not None:
                return r
        if hasattr(rhs, '_eval_Eq'):
            r = rhs._eval_Eq(lhs)
            if r is not None:
                return r
        # If expressions have the same structure, they must be equal.
        if lhs == rhs:
            return S.true  # e.g. True == True
        elif all(isinstance(i, BooleanAtom) for i in (rhs, lhs)):
            return S.false  # True != False
        elif not (lhs.is_Symbol or rhs.is_Symbol) and (
                isinstance(lhs, Boolean) !=
                isinstance(rhs, Boolean)):
            return S.false  # only Booleans can equal Booleans

        # check finiteness
        fin = L, R = [i.is_finite for i in (lhs, rhs)]
        if None not in fin:
            if L != R:
                return S.false
            if L is False:
                if lhs == -rhs:  # Eq(oo, -oo)
                    return S.false
                return S.true
        elif None in fin and False in fin:
            return Relational.__new__(cls, lhs, rhs, **options)

        if all(isinstance(i, Expr) for i in (lhs, rhs)):
            # see if the difference evaluates
            dif = lhs - rhs
            z = dif.is_zero
            if z is not None:
                if z is False and dif.is_commutative:  # issue 10728
                    return S.false
                if z:
                    return S.true
            # evaluate numerically if possible
            n2 = _n2(lhs, rhs)
            if n2 is not None:
                return _sympify(n2 == 0)
            # see if the ratio evaluates
            n, d = dif.as_numer_denom()
            rv = None
            if n.is_zero:
                rv = d.is_nonzero
            elif n.is_finite:
                if d.is_infinite:
                    rv = S.true
                elif n.is_zero is False:
                    rv = d.is_infinite
                    if rv is None:
                        # if the condition that makes the denominator infinite does not
                        # make the original expression True then False can be returned
                        l, r = clear_coefficients(d, S.Infinity)
                        args = [_.subs(l, r) for _ in (lhs, rhs)]
                        if args != [lhs, rhs]:
                            rv = fuzzy_bool(Eq(*args))
                            if rv is True:
                                rv = None
            elif any(a.is_infinite for a in Add.make_args(n)):  # (inf or nan)/x != 0
                rv = S.false
            if rv is not None:
                return _sympify(rv)

    return Relational.__new__(cls, lhs, rhs, **options)

def binary_symbols(self):
    if S.true in self.args or S.false in self.args:
        if self.lhs.is_Symbol:
            return set([self.lhs])
        elif self.rhs.is_Symbol:
            return set([self.rhs])
    return set()

def bottom_up(rv, F, atoms=False, nonbasic=False):
    """Apply ``F`` to all expressions in an expression tree from the
    bottom up. If ``atoms`` is True, apply ``F`` even if there are no args;
    if ``nonbasic`` is True, try to apply ``F`` to non-Basic objects.
    """
    args = getattr(rv, 'args', None)
    if args is not None:
        if args:
            args = tuple([bottom_up(a, F, atoms, nonbasic) for a in args])
            if args != rv.args:
                rv = rv.func(*args)
            rv = F(rv)
        elif atoms:
            rv = F(rv)
    else:
        if nonbasic:
            try:
                rv = F(rv)
            except TypeError:
                pass

    return rv

def __lt__(self, other):
    from sympy import StrictLessThan
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError("Invalid comparison %s < %s" % (self, other))
    for me in (self, other):
        if me.is_complex and me.is_extended_real is False:
            raise TypeError("Invalid comparison of complex %s" % me)
        if me is S.NaN:
            raise TypeError("Invalid NaN comparison")
    n2 = _n2(self, other)
    if n2 is not None:
        return _sympify(n2 < 0)
    if self.is_extended_real and other.is_extended_real:
        if (self.is_infinite and self.is_extended_positive) \
                or (other.is_infinite and other.is_extended_negative):
            return S.false
        neg = (self - other).is_extended_negative
        if neg is not None:
            return sympify(neg)
    return StrictLessThan(self, other, evaluate=False)

def _f(rv):
    # I'm not sure if this transformation should target all even powers
    # or only those expressible as powers of 2. Also, should it only
    # make the changes in powers that appear in sums -- making an isolated
    # change is not going to allow a simplification as far as I can tell.
    if not (rv.is_Pow and rv.base.func == f):
        return rv

    if (rv.exp < 0) == True:
        return rv
    if (rv.exp > max) == True:
        return rv
    if rv.exp == 2:
        return h(g(rv.base.args[0])**2)
    else:
        if rv.exp == 4:
            e = 2
        elif not pow:
            if rv.exp % 2:
                return rv
            e = rv.exp//2
        else:
            p = perfect_power(rv.exp)
            if not p:
                return rv
            e = rv.exp//2
        return h(g(rv.base.args[0])**2)**e

def __lt__(self, other):
    from sympy import StrictLessThan
    try:
        other = _sympify(other)
    except SympifyError:
        raise TypeError("Invalid comparison %s < %s" % (self, other))
    for me in (self, other):
        if me.is_complex and me.is_extended_real is False:
            raise TypeError("Invalid comparison of complex %s" % me)
        if me is S.NaN:
            raise TypeError("Invalid NaN comparison")
    n2 = _n2(self, other)
    if n2 is not None:
        return _sympify(n2 < 0)
    if self.is_extended_real and other.is_extended_real:
        if (self.is_infinite and self.is_extended_positive) \
                or (other.is_infinite and other.is_extended_negative):
            return S.false
        neg = (self - other).is_extended_negative
        if neg is not None:
            return sympify(neg)
    return StrictLessThan(self, other, evaluate=False)

def __getitem__(self, key):
    if not isinstance(key, tuple) and isinstance(key, slice):
        from sympy.matrices.expressions.slice import MatrixSlice
        return MatrixSlice(self, key, (0, None, 1))
    if isinstance(key, tuple) and len(key) == 2:
        i, j = key
        if isinstance(i, slice) or isinstance(j, slice):
            from sympy.matrices.expressions.slice import MatrixSlice
            return MatrixSlice(self, i, j)
        i, j = _sympify(i), _sympify(j)
        if self.valid_index(i, j) != False:
            return self._entry(i, j)
        else:
            raise IndexError("Invalid indices (%s, %s)" % (i, j))
    elif isinstance(key, (SYMPY_INTS, Integer)):
        # row-wise decomposition of matrix
        rows, cols = self.shape
        # allow single indexing if number of columns is known
        if not isinstance(cols, Integer):
            raise IndexError(filldedent('''
                Single indexing is only supported when the number
                of columns is known.'''))
        key = _sympify(key)
        i = key // cols
        j = key % cols
        if self.valid_index(i, j) != False:
            return self._entry(i, j)
        else:
            raise IndexError("Invalid index %s" % key)
    elif isinstance(key, (Symbol, Expr)):
            raise IndexError(filldedent('''
                Only integers may be used when addressing the matrix
                with a single index.'''))
    raise IndexError("Invalid index, wanted %s[i,j]" % self)

def _entry(self, i, j, **kwargs):
    # Find row entry
    for row_block, numrows in enumerate(self.rowblocksizes):
        if (i < numrows) != False:
            break
        else:
            i -= numrows
    for col_block, numcols in enumerate(self.colblocksizes):
        if (j < numcols) != False:
            break
        else:
            j -= numcols
    return self.blocks[row_block, col_block][i, j]

def multiset_permutations(m, size=None, g=None):
    """
    Return the unique permutations of multiset ``m``.

    Examples
    ========

    >>> from sympy.utilities.iterables import multiset_permutations
    >>> from sympy import factorial
    >>> [''.join(i) for i in multiset_permutations('aab')]
    ['aab', 'aba', 'baa']
    >>> factorial(len('banana'))
    720
    >>> len(list(multiset_permutations('banana')))
    60
    """
    if g is None:
        if type(m) is dict:
            g = [[k, m[k]] for k in ordered(m)]
        else:
            m = list(ordered(m))
            g = [list(i) for i in group(m, multiple=False)]
        del m
    do = [gi for gi in g if gi[1] > 0]
    SUM = sum([gi[1] for gi in do])
    if not do or size is not None and (size > SUM or size < 1):
        if size < 1:
            yield []
        return
    elif size == 1:
        for k, v in do:
            yield [k]
    elif len(do) == 1:
        k, v = do[0]
        v = v if size is None else (size if size <= v else 0)
        yield [k for i in range(v)]
    elif all(v == 1 for k, v in do):
        for p in permutations([k for k, v in do], size):
            yield list(p)
    else:
        size = size if size is not None else SUM
        for i, (k, v) in enumerate(do):
            do[i][1] -= 1
            for j in multiset_permutations(None, size - 1, do):
                if j:
                    yield [k] + j
            do[i][1] += 1

def _is_univariate(f):
    """Returns True if 'f' is univariate in its last variable. """
    for monom in f.monoms():
        if any(monom[:-1]):
            return False

    return True

def _subs_root(f, gen, zero):
    """Replace generator with a root so that the result is nice. """
    p = f.as_expr({gen: zero})

    if f.degree(gen) >= 2:
        p = p.expand(deep=False)

    return p

def _solve_reduced_system(system, gens, entry=False):
    """Recursively solves reduced polynomial systems. """
    if len(system) == len(gens) == 1:
        zeros = list(roots(system[0], gens[-1]).keys())
        return [(zero,) for zero in zeros]

    basis = groebner(system, gens, polys=True)

    if len(basis) == 1 and basis[0].is_ground:
        if not entry:
            return []
        else:
            return None

    univariate = list(filter(_is_univariate, basis))

    if len(univariate) == 1:
        f = univariate.pop()
    else:
        raise NotImplementedError(filldedent('''
            only zero-dimensional systems supported
            (finite number of solutions)
            '''))

    gens = f.gens
    gen = gens[-1]

    zeros = list(roots(f.ltrim(gen)).keys())

    if not zeros:
        return []

    if len(basis) == 1:
        return [(zero,) for zero in zeros]

    solutions = []

    for zero in zeros:
        new_system = []
        new_gens = gens[:-1]

        for b in basis[:-1]:
            eq = _subs_root(b, gen, zero)

            if eq is not S.Zero:
                new_system.append(eq)

        for solution in _solve_reduced_system(new_system, new_gens):
            solutions.append(solution + (zero,))

    if solutions and len(solutions[0]) != len(gens):
        raise NotImplementedError(filldedent('''
            only zero-dimensional systems supported
            (finite number of solutions)
            '''))
    return solutions

def _collect_factor_and_dimension(self, expr):
    """
    Return tuple with scale factor expression and dimension expression.
    """
    from sympy.physics.units import Quantity
    if isinstance(expr, Quantity):
        return expr.scale_factor, expr.dimension
    elif isinstance(expr, Mul):
        factor = 1
        dimension = Dimension(1)
        for arg in expr.args:
            arg_factor, arg_dim = self._collect_factor_and_dimension(arg)
            factor *= arg_factor
            dimension *= arg_dim
        return factor, dimension
    elif isinstance(expr, Pow):
        factor, dim = self._collect_factor_and_dimension(expr.base)
        exp_factor, exp_dim = self._collect_factor_and_dimension(expr.exp)
        if self.get_dimension_system().is_dimensionless(exp_dim):
            exp_dim = 1
        return factor ** exp_factor, dim ** (exp_factor * exp_dim)
    elif isinstance(expr, Add):
        factor, dim = self._collect_factor_and_dimension(expr.args[0])
        for addend in expr.args[1:]:
            addend_factor, addend_dim = \
                self._collect_factor_and_dimension(addend)
            if dim != addend_dim:
                raise ValueError(
                    'Dimension of "{}" is {}, '
                    'but it should be {}'.format(
                        addend, addend_dim, dim))
            factor += addend_factor
        return factor, dim
    elif isinstance(expr, Derivative):
        factor, dim = self._collect_factor_and_dimension(expr.args[0])
        for independent, count in expr.variable_count:
            ifactor, idim = self._collect_factor_and_dimension(independent)
            factor /= ifactor**count
            dim /= idim**count
        return factor, dim
    elif isinstance(expr, Function):
        fds = [self._collect_factor_and_dimension(arg) for arg in expr.args]
        dims = [Dimension(1) if self.get_dimension_system().is_dimensionless(d[1]) else d[1] for d in fds]
        return (expr.func(*(f[0] for f in fds)), *dims)
    elif isinstance(expr, Dimension):
        return S.One, expr
    else:
        return expr, Dimension(1)

def get_dimensional_dependencies(self, name, mark_dimensionless=False):
    dimdep = self._get_dimensional_dependencies_for_name(name)
    if mark_dimensionless and dimdep == {}:
        return {Dimension(1): 1}
    return {k: v for k, v in dimdep.items()}

def _get_dimensional_dependencies_for_name(self, dimension):
    if isinstance(dimension, str):
        dimension = Dimension(Symbol(dimension))
    elif not isinstance(dimension, Dimension):
        dimension = Dimension(dimension)

    if dimension.name.is_Symbol:
        # Dimensions not included in the dependencies are considered
        # as base dimensions:
        return dict(self.dimensional_dependencies.get(dimension, {dimension: 1}))

    if dimension.name.is_number or dimension.name.is_NumberSymbol:
        return {}

    get_for_name = self._get_dimensional_dependencies_for_name

    if dimension.name.is_Mul:
        ret = collections.defaultdict(int)
        dicts = [get_for_name(i) for i in dimension.name.args]
        for d in dicts:
            for k, v in d.items():
                ret[k] += v
        return {k: v for (k, v) in ret.items() if v != 0}

    if dimension.name.is_Add:
        dicts = [get_for_name(i) for i in dimension.name.args]
        if all(d == dicts[0] for d in dicts[1:]):
            return dicts[0]
        raise TypeError("Only equivalent dimensions can be added or subtracted.")

    if dimension.name.is_Pow:
        dim_base = get_for_name(dimension.name.base)
        dim_exp = get_for_name(dimension.name.exp)
        if dim_exp == {} or dimension.name.exp.is_Symbol:
            return {k: v * dimension.name.exp for (k, v) in dim_base.items()}
        else:
            raise TypeError("The exponent for the power operator must be a Symbol or dimensionless.")

    if dimension.name.is_Function:
        args = (Dimension._from_dimensional_dependencies(
            get_for_name(arg)) for arg in dimension.name.args)
        result = dimension.name.func(*args)

        dicts = [get_for_name(i) for i in dimension.name.args]

        if isinstance(result, Dimension):
            return self.get_dimensional_dependencies(result)
        elif result.func == dimension.name.func:
            if isinstance(dimension.name, TrigonometricFunction):
                if dicts[0] in ({}, {Dimension('angle'): 1}):
                    return {}
                else:
                    raise TypeError("The input argument for the function {} must be dimensionless or have dimensions of angle.".format(dimension.func))
            else:
                if all(item == {} for item in dicts):
                    return {}
                else:
                    raise TypeError("The input arguments for the function {} must be dimensionless.".format(dimension.func))
        else:
            return get_for_name(result)

    raise TypeError("Type {} not implemented for get_dimensional_dependencies".format(type(dimension.name)))

def get_quantity_dimension(self, unit):
    qdm = self.get_dimension_system()._quantity_dimension_map
    if unit in qdm:
        return qdm[unit]
    return super().get_quantity_dimension(unit)

def get_quantity_scale_factor(self, unit):
    qsfm = self.get_dimension_system()._quantity_scale_factors
    if unit in qsfm:
        return qsfm[unit]
    return super().get_quantity_scale_factor(unit)

def dim(self):
    """
    Give the dimension of the system.

    That is return the number of units forming the basis.
    """
    return len(self._base_units)

def get_default(self):
    """Return the default value for this field."""
    return self._get_default()

def serialize(self):
    attr_name, path, args, kwargs = self.value.deconstruct()
    return self.serialize_deconstructed(path, args, kwargs)

def get_formset(self, request, obj=None, **kwargs):
    """Return a BaseInlineFormSet class for use in admin add/change views."""
    if "fields" in kwargs:
        fields = kwargs.pop("fields")
    else:
        fields = flatten_fieldsets(self.get_fieldsets(request, obj))
    excluded = self.get_exclude(request, obj)
    exclude = [] if excluded is None else list(excluded)
    exclude.extend(self.get_readonly_fields(request, obj))
    if excluded is None and hasattr(self.form, "_meta") and self.form._meta.exclude:
        # Take the custom ModelForm's Meta.exclude into account only if the
        # InlineModelAdmin doesn't define its own.
        exclude.extend(self.form._meta.exclude)
    # If exclude is an empty list we use None, since that's the actual
    # default.
    exclude = exclude or None
    can_delete = self.can_delete and self.has_delete_permission(request, obj)
    defaults = {
        "form": self.form,
        "formset": self.formset,
        "fk_name": self.fk_name,
        "fields": fields,
        "exclude": exclude,
        "formfield_callback": partial(self.formfield_for_dbfield, request=request),
        "extra": self.get_extra(request, obj, **kwargs),
        "min_num": self.get_min_num(request, obj, **kwargs),
        "max_num": self.get_max_num(request, obj, **kwargs),
        "can_delete": can_delete,
        **kwargs,
    }

    base_model_form = defaults["form"]
    can_change = self.has_change_permission(request, obj) if request else True
    can_add = self.has_add_permission(request, obj) if request else True

    class DeleteProtectedModelForm(base_model_form):
        def hand_clean_DELETE(self):
            """
            We don't validate the 'DELETE' field itself because on
            templates it's not rendered using the field information, but
            just using a generic "deletion_field" of the InlineModelAdmin.
            """
            if self.cleaned_data.get(DELETION_FIELD_NAME, False):
                using = router.db_for_write(self._meta.model)
                collector = NestedObjects(using=using)
                if self.instance._state.adding:
                    return
                collector.collect([self.instance])
                if collector.protected:
                    objs = []
                    for p in collector.protected:
                        objs.append(
                            # Translators: Model verbose name and instance
                            # representation, suitable to be an item in a
                            # list.
                            _("%(class_name)s %(instance)s")
                            % {"class_name": p._meta.verbose_name, "instance": p}
                        )
                    params = {
                        "class_name": self._meta.model._meta.verbose_name,
                        "instance": self.instance,
                        "related_objects": get_text_list(objs, _("and")),
                    }
                    msg = _(
                        "Deleting %(class_name)s %(instance)s would require "
                        "deleting the following protected related objects: "
                        "%(related_objects)s"
                    )
                    raise ValidationError(
                        msg, code="deleting_protected", params=params
                    )

        def is_valid(self):
            result = super().is_valid()
            self.hand_clean_DELETE()
            return result

        def has_changed(self):
            # Protect against unauthorized edits.
            if not can_change and not self.instance._state.adding:
                return False
            if not can_add and self.instance._state.adding:
                return False
            return super().has_changed()

    defaults["form"] = DeleteProtectedModelForm

    if defaults["fields"] is None and not modelform_defines_fields(
        defaults["form"]
    ):
        defaults["fields"] = forms.ALL_FIELDS

    return inlineformset_factory(self.parent_model, self.model, **defaults)

def clean(self):
    self._validate_unique = True
    return self.cleaned_data

def _clean_fields(self):
    for name, bf in self._bound_items():
        field = bf.field
        value = bf.initial if field.disabled else bf.data
        try:
            if isinstance(field, FileField):
                value = field.clean(value, bf.initial)
            else:
                value = field.clean(value)
            self.cleaned_data[name] = value
            if hasattr(self, "clean_%s" % name):
                value = getattr(self, "clean_%s" % name)()
                self.cleaned_data[name] = value
        except ValidationError as e:
            self.add_error(name, e)

def _clean_form(self):
    try:
        cleaned_data = self.clean()
    except ValidationError as e:
        self.add_error(None, e)
    else:
        if cleaned_data is not None:
            self.cleaned_data = cleaned_data

def destroy_fig(cls, fig):
    """Destroy figure *fig*."""
    num = next((manager.num for manager in cls.figs.values()
                if manager.canvas.figure == fig), None)
    if num is not None:
        cls.destroy(num)

def has_fignum(cls, num):
    """Return whether figure number *num* exists."""
    return num in cls.figs

def get_all_fig_managers(cls):
    """Return a list of figure managers."""
    return list(cls.figs.values())

def get_fig_manager(cls, num):
    """
    If manager number *num* exists, make it the active one and return it;
    otherwise return *None*.
    """
    manager = cls.figs.get(num, None)
    if manager is not None:
        cls.set_active(manager)
    return manager

def gcf():
    """
    Get the current figure.

    If there is currently no figure on the pyplot figure stack, a new one is
    created using `~.pyplot.figure()`.  (To test whether there is currently a
    figure on the pyplot figure stack, check whether `~.pyplot.get_fignums()`
    is empty.)
    """
    manager = _pylab_helpers.Gcf.get_active()
    if manager is not None:
        return manager.canvas.figure
    else:
        return figure()

def new_figure_manager(*args, **kwargs):
    """Create a new figure manager instance."""
