def get_constrained_layout(self):
    """
    Return whether constrained layout is being used.

    See :doc:`/tutorials/intermediate/constrainedlayout_guide`.
    """
    return isinstance(self.get_layout_engine(), ConstrainedLayoutEngine)

def get_subplotspec_list(axes_list, grid_spec=None):
    """
    Return a list of subplotspec from the given list of axes.

    For an instance of axes that does not support subplotspec, None is inserted
    in the list.

    If grid_spec is given, None is inserted for those not from the given
    grid_spec.
    """
    subplotspec_list = []
    for ax in axes_list:
        axes_or_locator = ax.get_axes_locator()
        if axes_or_locator is None:
            axes_or_locator = ax

        if hasattr(axes_or_locator, "get_subplotspec"):
            subplotspec = axes_or_locator.get_subplotspec()
            if subplotspec is not None:
                subplotspec = subplotspec.get_topmost_subplotspec()
                gs = subplotspec.get_gridspec()
                if grid_spec is not None:
                    if gs != grid_spec:
                        subplotspec = None
                elif gs.locally_modified_subplot_params():
                    subplotspec = None
        else:
            subplotspec = None

        subplotspec_list.append(subplotspec)

    return subplotspec_list

def flush_events(self):
    # docstring inherited
    QtWidgets.QApplication.instance().processEvents()

def _draw_idle(self):
    with self._idle_draw_cntx():
        if not self._draw_pending:
            return
        self._draw_pending = False
        if self.height() < 0 or self.width() < 0:
            return
        try:
            self.draw()
        except Exception:
            # Uncaught exceptions are fatal for PyQt5, so catch them.
            traceback.print_exc()

def _get_draw_artists(self, renderer):
    """Also runs apply_aspect"""
    artists = self.get_children()
    for sfig in self.subfigs:
        artists.remove(sfig)
        childa = sfig.get_children()
        for child in childa:
            if child in artists:
                artists.remove(child)

    artists.remove(self.patch)
    artists = sorted(
        (artist for artist in artists if not artist.get_animated()),
        key=lambda artist: artist.get_zorder())
    for ax in self._localaxes:
        locator = ax.get_axes_locator()
        ax.apply_aspect(locator(ax, renderer) if locator else None)

        for child in ax.get_children():
            if hasattr(child, 'apply_aspect'):
                locator = child.get_axes_locator()
                child.apply_aspect(
                    locator(child, renderer) if locator else None)
    return artists

def _set_facecolor(self, c):
    if c is None:
        c = self._get_default_facecolor()

    self._facecolors = mcolors.to_rgba_array(c, self._alpha)
    self.stale = True

def _get_default_facecolor(self):
    # This may be overridden in a subclass.
    return mpl.rcParams['patch.facecolor']

def clf():
    """Clear the current figure."""
    gcf().clear()

def draw(self, renderer):
    # docstring inherited

    # draw the figure bounding box, perhaps none for white figure
    if not self.get_visible():
        return

    artists = self._get_draw_artists(renderer)
    try:
        renderer.open_group('figure', gid=self.get_gid())
        if self.axes and self.get_layout_engine() is not None:
            try:
                self.get_layout_engine().execute(self)
            except ValueError:
                pass
                # ValueError can occur when resizing a window.

        self.patch.draw(renderer)
        mimage._draw_list_compositing_images(
            renderer, self, artists, self.suppressComposite)

        for sfig in self.subfigs:
            sfig.draw(renderer)

        renderer.close_group('figure')
    finally:
        self.stale = False

    DrawEvent("draw_event", self.canvas, renderer)._process()

def _filter_subplot_data(self, df: DataFrame, subplot: dict) -> DataFrame:
    # TODO note redundancies with preceding function ... needs refactoring
    dims = df.columns.intersection(["col", "row"])
    if dims.empty:
        return df

    keep_rows = pd.Series(True, df.index, dtype=bool)
    for dim in dims:
        keep_rows &= df[dim] == subplot[dim]
    return df[keep_rows]

def _reorder_columns(self, res, data):
    """Reorder result columns to match original order with new columns appended."""
    cols = [c for c in data if c in res]
    cols += [c for c in res if c not in data]
    return res.reindex(columns=pd.Index(cols))

def _compute_stats(self, spec: Plot, layers: list[Layer]) -> None:

    grouping_vars = [v for v in PROPERTIES if v not in "xy"]
    grouping_vars += ["col", "row", "group"]

    pair_vars = spec._pair_spec.get("structure", {})

    for layer in layers:

        data = layer["data"]
        mark = layer["mark"]
        stat = layer["stat"]

        if stat is None:
            continue

        iter_axes = itertools.product(*[
            pair_vars.get(axis, [axis]) for axis in "xy"
        ])

        old = data.frame

        if pair_vars:
            data.frames = {}
            data.frame = data.frame.iloc[:0]  # TODO to simplify typing

        for coord_vars in iter_axes:

            pairings = "xy", coord_vars

            df = old.copy()
            scales = self._scales.copy()

            for axis, var in zip(*pairings):
                if axis != var:
                    df = df.rename(columns={var: axis})
                    drop_cols = [x for x in df if re.match(rf"{axis}\d+", x)]
                    df = df.drop(drop_cols, axis=1)
                    scales[axis] = scales[var]

            orient = layer["orient"] or mark._infer_orient(scales)

            if stat.group_by_orient:
                grouper = [orient, *grouping_vars]
            else:
                grouper = grouping_vars
            groupby = GroupBy(grouper)
            res = stat(df, groupby, orient, scales)

            if pair_vars:
                data.frames[coord_vars] = res
            else:
                data.frame = res

def _get_scale(
    self, spec: Plot, var: str, prop: Property, values: Series
) -> ScaleSpec:

    if var in spec._scales:
        arg = spec._scales[var]
        if arg is None or isinstance(arg, ScaleSpec):
            scale = arg
        else:
            scale = prop.infer_scale(arg, values)
    else:
        scale = prop.default_scale(values)

    return scale

def connect(self):
    conn = self._new_conn()
    self._prepare_conn(conn)

def content(self):
    """Content of the response, in bytes."""

    if self._content is False:
        # Read the contents.
        try:
            if self._content_consumed:
                raise RuntimeError(
                    'The content for this response was already consumed')

            if self.status_code == 0:
                self._content = None
            else:
                self._content = bytes().join(self.iter_content(CONTENT_CHUNK_SIZE)) or bytes()

        except AttributeError:
            self._content = None

    self._content_consumed = True
    # don't need to release the connection; that's been handled by urllib3
    # since we exhausted the data.
    return self._content

def iter_content(self, chunk_size=1, decode_unicode=False):
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    If decode_unicode is True, content will be decoded using the best
    available encoding based on the response.
    """
    def generate():
        try:
            # Special case for urllib3.
            try:
                for chunk in self.raw.stream(chunk_size, decode_content=True):
                    yield chunk
            except IncompleteRead as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
        except AttributeError:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    # simulate reading small chunks of the content
    reused_chunks = iter_slices(self._content, chunk_size)

    stream_chunks = generate()

    chunks = reused_chunks if self._content_consumed else stream_chunks

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def content(self):
    """Content of the response, in bytes."""

    if self._content is False:
        # Read the contents.
        try:
            if self._content_consumed:
                raise RuntimeError(
                    'The content for this response was already consumed')

            if self.status_code == 0:
                self._content = None
            else:
                self._content = bytes().join(self.iter_content(CONTENT_CHUNK_SIZE)) or bytes()

        except AttributeError:
            self._content = None

    self._content_consumed = True
    # don't need to release the connection; that's been handled by urllib3
    # since we exhausted the data.
    return self._content

def get_encoding_from_headers(headers):
    """Returns encodings from given HTTP Header Dict.

    :param headers: dictionary to extract encoding from.
    """

    content_type = headers.get('content-type')

    if not content_type:
        return None

    content_type, params = cgi.parse_header(content_type)

    if 'charset' in params:
        return params['charset'].strip("'\"")

    if 'text' in content_type:
        return 'ISO-8859-1'

def apparent_encoding(self):
    """The apparent encoding, provided by the chardet library"""
    return chardet.detect(self.content)['encoding']

def json(self, **kwargs):
    """Returns the json-encoded content of a response, if any.

    :param \*\*kwargs: Optional arguments that ``json.loads`` takes.
    """

    if not self.encoding and self.content and len(self.content) > 3:
        # No encoding set. JSON RFC 4627 section 3 states we should expect
        # UTF-8, -16 or -32. Detect which one to use; If the detection or
        # decoding fails, fall back to `self.text` (using chardet to make
        # a best guess).
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return complexjson.loads(
                    self.content.decode(encoding), **kwargs
                )
            except UnicodeDecodeError:
                # Wrong UTF codec detected; usually because it's not UTF-8
                # but some other 8-bit codec.  This is an RFC violation,
                # and the server didn't bother to tell us what codec *was*
                # used.
                pass
    return complexjson.loads(self.text, **kwargs)

def raise_for_status(self):
    """Raises stored :class:`HTTPError`, if one occurred."""

    http_error_msg = ''

    if 400 <= self.status_code < 500:
        http_error_msg = '%s Client Error: %s for url: %s' % (self.status_code, self.reason, self.url)

    elif 500 <= self.status_code < 600:
        http_error_msg = '%s Server Error: %s for url: %s' % (self.status_code, self.reason, self.url)

    if http_error_msg:
        raise HTTPError(http_error_msg, response=self)

def close(self):
    """Releases the connection back to the pool. Once this method has been
    called the underlying ``raw`` object must not be accessed again.

    *Note: Should not normally need to be called explicitly.*
    """
    if not self._content_consumed:
        return self.raw.close()

    return self.raw.release_conn()

def dataset_repr(ds):
    summary = ["<xarray.{}>".format(type(ds).__name__)]

    col_width = _calculate_col_width(_get_col_items(ds.variables))

    dims_start = pretty_print("Dimensions:", col_width)
    summary.append("{}({})".format(dims_start, dim_summary(ds)))

    if ds.coords:
        summary.append(coords_repr(ds.coords, col_width=col_width))

    unindexed_dims_str = unindexed_dims_repr(ds.dims, ds.coords)
    if unindexed_dims_str:
        summary.append(unindexed_dims_str)

    summary.append(data_vars_repr(ds.data_vars, col_width=col_width))

    if ds.attrs:
        summary.append(attrs_repr(ds.attrs))

    return "\n".join(summary)

def coords_repr(coords, col_width=None):
    if col_width is None:
        col_width = _calculate_col_width(_get_col_items(coords))
    return _mapping_repr(
        coords, title="Coordinates", summarizer=summarize_coord, col_width=col_width
    )

def summarize_coord(name: Hashable, var, col_width: int):
    is_index = name in var.dims
    marker = "*" if is_index else " "
    if is_index:
        coord = var.variable.to_index_variable()
        if coord.level_names is not None:
            return "\n".join(
                [
                    _summarize_coord_multiindex(coord, col_width, marker),
                    _summarize_coord_levels(coord, col_width),
                ]
            )
    return summarize_variable(name, var.variable, col_width, marker)

def summarize_variable(
    name: Hashable, var, col_width: int, marker: str = " ", max_width: int = None
):
    """Summarize a variable in one line, e.g., for the Dataset.__repr__."""
    if max_width is None:
        max_width_options = OPTIONS["display_width"]
        if not isinstance(max_width_options, int):
            raise TypeError(f"`max_width` value of `{max_width}` is not a valid int")
        else:
            max_width = max_width_options
    first_col = pretty_print(f"  {marker} {name} ", col_width)
    if var.dims:
        dims_str = "({}) ".format(", ".join(map(str, var.dims)))
    else:
        dims_str = ""
    front_str = f"{first_col}{dims_str}{var.dtype} "

    values_width = max_width - len(front_str)
    values_str = inline_variable_array_repr(var, values_width)

    return front_str + values_str

def inline_variable_array_repr(var, max_width):
    """Build a one-line summary of a variable's data."""
    if var._in_memory:
        return format_array_flat(var, max_width)
    elif isinstance(var._data, dask_array_type):
        return inline_dask_repr(var.data)
    elif isinstance(var._data, sparse_array_type):
        return inline_sparse_repr(var.data)
    elif hasattr(var._data, "__array_function__"):
        return maybe_truncate(repr(var._data).replace("\n", " "), max_width)
    else:
        # internal xarray array type
        return "..."

def dim_summary(obj):
    elements = [f"{k}: {v}" for k, v in obj.sizes.items()]
    return ", ".join(elements)

def coords(self) -> DatasetCoordinates:
    """Dictionary of xarray.DataArray objects corresponding to coordinate
    variables
    """
    return DatasetCoordinates(self)

def merge_collected(
    grouped: Dict[Hashable, List[MergeElement]],
    prioritized: Mapping[Hashable, MergeElement] = None,
    compat: str = "minimal",
) -> Tuple[Dict[Hashable, Variable], Dict[Hashable, pd.Index]]:
    """Merge dicts of variables, while resolving conflicts appropriately.

    Parameters
    ----------
    grouped : mapping
    prioritized : mapping
    compat : str
        Type of equality check to use when checking for conflicts.

    Returns
    -------
    Dict with keys taken by the union of keys on list_of_mappings,
    and Variable values corresponding to those that should be found on the
    merged result.
    """
    if prioritized is None:
        prioritized = {}

    _assert_compat_valid(compat)

    merged_vars: Dict[Hashable, Variable] = {}
    merged_indexes: Dict[Hashable, pd.Index] = {}

    for name, elements_list in grouped.items():
        if name in prioritized:
            variable, index = prioritized[name]
            merged_vars[name] = variable
            if index is not None:
                merged_indexes[name] = index
        else:
            indexed_elements = [
                (variable, index)
                for variable, index in elements_list
                if index is not None
            ]

            if indexed_elements:
                # TODO(shoyer): consider adjusting this logic. Are we really
                # OK throwing away variable without an index in favor of
                # indexed variables, without even checking if values match?
                variable, index = indexed_elements[0]
                for _, other_index in indexed_elements[1:]:
                    if not index.equals(other_index):
                        raise MergeError(
                            "conflicting values for index %r on objects to be "
                            "combined:\nfirst value: %r\nsecond value: %r"
                            % (name, index, other_index)
                        )
                if compat == "identical":
                    for other_variable, _ in indexed_elements[1:]:
                        if not dict_equiv(variable.attrs, other_variable.attrs):
                            raise MergeError(
                                "conflicting attribute values on combined "
                                "variable %r:\nfirst value: %r\nsecond value: %r"
                                % (name, variable.attrs, other_variable.attrs)
                            )
                merged_vars[name] = variable
                merged_indexes[name] = index
            else:
                variables = [variable for variable, _ in elements_list]
                try:
                    merged_vars[name] = unique_variable(name, variables, compat)
                except MergeError:
                    if compat != "minimal":
                        # we need more than "minimal" compatibility (for which
                        # we drop conflicting coordinates)
                        raise

    return merged_vars, merged_indexes

def _replace(
    self,
    variables: Dict[Hashable, Variable] = None,
    coord_names: Set[Hashable] = None,
    dims: Dict[Any, int] = None,
    attrs: Union[Dict[Hashable, Any], None, Default] = _default,
    indexes: Union[Dict[Any, pd.Index], None, Default] = _default,
    encoding: Union[dict, None, Default] = _default,
    inplace: bool = False,
) -> "Dataset":
    """Fastpath constructor for internal use.

    Returns an object with optionally with replaced attributes.

    Explicitly passed arguments are *not* copied when placed on the new
    dataset. It is up to the caller to ensure that they have the right type
    and are not used elsewhere.
    """
    if inplace:
        if variables is not None:
            self._variables = variables
        if coord_names is not None:
            self._coord_names = coord_names
        if dims is not None:
            self._dims = dims
        if attrs is not _default:
            self._attrs = attrs
        if indexes is not _default:
            self._indexes = indexes
        if encoding is not _default:
            self._encoding = encoding
        obj = self
    else:
        if variables is None:
            variables = self._variables.copy()
        if coord_names is None:
            coord_names = self._coord_names.copy()
        if dims is None:
            dims = self._dims.copy()
        if attrs is _default:
            attrs = copy.copy(self._attrs)
        if indexes is _default:
            indexes = copy.copy(self._indexes)
        if encoding is _default:
            encoding = copy.copy(self._encoding)
        obj = self._construct_direct(
            variables, coord_names, dims, attrs, indexes, encoding
        )
    return obj

def _overwrite_indexes(self, indexes: Mapping[Any, pd.Index]) -> "Dataset":
    if not indexes:
        return self

    variables = self._variables.copy()
    new_indexes = dict(self.indexes)
    for name, idx in indexes.items():
        variables[name] = IndexVariable(name, idx)
        new_indexes[name] = idx
    obj = self._replace(variables, indexes=new_indexes)

    # switch from dimension to level names, if necessary
    dim_names: Dict[Hashable, str] = {}
    for dim, idx in indexes.items():
        if not isinstance(idx, pd.MultiIndex) and idx.name != dim:
            dim_names[dim] = idx.name
    if dim_names:
        obj = obj.rename(dim_names)
    return obj

def _validate_indexers(
    self, indexers: Mapping[Hashable, Any], missing_dims: str = "raise"
) -> Iterator[Tuple[Hashable, Union[int, slice, np.ndarray, Variable]]]:
    """Here we make sure
    + indexer has a valid keys
    + indexer is in a valid data type
    + string indexers are cast to the appropriate date type if the
      associated index is a DatetimeIndex or CFTimeIndex
    """
    from .dataarray import DataArray

    indexers = drop_dims_from_indexers(indexers, self.dims, missing_dims)

    # all indexers should be int, slice, np.ndarrays, or Variable
    for k, v in indexers.items():
        if isinstance(v, (int, slice, Variable)):
            yield k, v
        elif isinstance(v, DataArray):
            yield k, v.variable
        elif isinstance(v, tuple):
            yield k, as_variable(v)
        elif isinstance(v, Dataset):
            raise TypeError("cannot use a Dataset as an indexer")
        elif isinstance(v, Sequence) and len(v) == 0:
            yield k, np.empty((0,), dtype="int64")
        else:
            v = np.asarray(v)

            if v.dtype.kind in "US":
                index = self.indexes[k]
                if isinstance(index, pd.DatetimeIndex):
                    v = v.astype("datetime64[ns]")
                elif isinstance(index, xr.CFTimeIndex):
                    v = _parse_array_of_cftime_strings(v, index.date_type)

            if v.ndim > 1:
                raise IndexError(
                    "Unlabeled multi-dimensional array cannot be "
                    "used for indexing: {}".format(k)
                )
            yield k, v

def _parse_toml(self, config_file: Path, parser: configparser.ConfigParser) -> None:
    """Parse and handle errors of a toml configuration file."""
    with open(config_file, mode="rb") as fp:
        content = tomllib.load(fp)
    try:
        sections_values = content["tool"]["pylint"]
    except KeyError:
        return
    for section, values in sections_values.items():
        section_name = section.upper()
        # TOML has rich types, convert values to
        # strings as ConfigParser expects.
        if not isinstance(values, dict):
            # This class is a mixin: add_message comes from the `PyLinter` class
            self.add_message(  # type: ignore[attr-defined]
                "bad-configuration-section", line=0, args=(section, values)
            )
            continue
        for option, value in values.items():
            if isinstance(value, bool):
                values[option] = "yes" if value else "no"
            elif isinstance(value, list):
                values[option] = ",".join(value)
            else:
                values[option] = str(value)
        for option, value in values.items():
            try:
                parser.set(section_name, option, value=value)
            except configparser.NoSectionError:
                parser.add_section(section_name)
                parser.set(section_name, option, value=value)

def load_provider_defaults(self):
    """Initialize configuration using default values."""
    for provider in self.options_providers:
        provider.load_defaults()

def generate_config(
    self, stream: TextIO | None = None, skipsections: tuple[str, ...] = ()
) -> None:
    """Write a configuration file according to the current configuration
    into the given stream or stdout.
    """
    options_by_section: dict[str, list[tuple[str, OptionDict, Any]]] = {}
    sections = []
    for provider in self.options_providers:
        for section, options in provider.options_by_section():
            if section is None:
                section = provider.name
            if section in skipsections:
                continue
            options = [
                (n, d, v)
                for (n, d, v) in options
                if d.get("type") is not None and not d.get("deprecated")
            ]
            if not options:
                continue
            if section not in sections:
                sections.append(section)
            all_options = options_by_section.setdefault(section, [])
            all_options += options
    stream = stream or sys.stdout
    printed = False
    for section in sections:
        if printed:
            print("\n", file=stream)
        utils.format_section(
            stream, section.upper(), sorted(options_by_section[section])
        )
        printed = True

def read_config_file(
    self, config_file: Path | None = None, verbose: bool = False
) -> None:
    """Read the configuration file but do not load it (i.e. dispatching
    values to each option's provider).
    """
    if config_file:
        config_file = Path(os.path.expandvars(config_file)).expanduser()
        if not config_file.exists():
            raise OSError(f"The config file {str(config_file)} doesn't exist!")

        parser = self.cfgfile_parser
        if config_file.suffix == ".toml":
            try:
                self._parse_toml(config_file, parser)
            except tomllib.TOMLDecodeError:
                pass
        else:
            # Use this encoding in order to strip the BOM marker, if any.
            with open(config_file, encoding="utf_8_sig") as fp:
                parser.read_file(fp)
            # normalize each section's title
            for sect, values in list(parser._sections.items()):
                if sect.startswith("pylint."):
                    sect = sect[len("pylint.") :]
                if not sect.isupper() and values:
                    parser._sections[sect.upper()] = values

    if not verbose:
        return
    if config_file and config_file.exists():
        msg = f"Using config file '{config_file}'"
    else:
        msg = "No config file found, using default configuration"
    print(msg, file=sys.stderr)

def load_configuration_from_config(self, config):
    for opt, opt_value in config.items():
        opt = opt.replace("_", "-")
        provider = self._all_options[opt]
        provider.set_option(opt, opt_value)

def getfixtureinfo(self, node, func, cls, funcargs=True):
    if funcargs and not getattr(node, "nofuncargs", False):
        argnames = getfuncargnames(func, cls=cls)
    else:
        argnames = ()
    usefixtures = itertools.chain.from_iterable(
        mark.args for mark in node.iter_markers(name="usefixtures")
    )
    initialnames = tuple(usefixtures) + argnames
    fm = node.session._fixturemanager
    initialnames, names_closure, arg2fixturedefs = fm.getfixtureclosure(
        initialnames, node
    )
    return FuncFixtureInfo(argnames, initialnames, names_closure, arg2fixturedefs)

def pytest_report_header(self, config):
    line = "rootdir: %s" % config.rootdir

    if config.inifile:
        line += ", inifile: " + config.rootdir.bestrelpath(config.inifile)

    testpaths = config.getini("testpaths")
    if testpaths and config.args == testpaths:
        rel_paths = [config.rootdir.bestrelpath(x) for x in testpaths]
        line += ", testpaths: {}".format(", ".join(rel_paths))
    result = [line]

    plugininfo = config.pluginmanager.list_plugin_distinfo()
    if plugininfo:
        result.append("plugins: %s" % ", ".join(_plugin_nameversions(plugininfo)))
    return result

def pytest_cmdline_parse(self, pluginmanager, args):
    try:
        self.parse(args)
    except UsageError:

        # Handle --version and --help here in a minimal fashion.
        # This gets done via helpconfig normally, but its
        # pytest_cmdline_main is not called in case of errors.
        if getattr(self.option, "version", False) or "--version" in args:
            from _pytest.helpconfig import showversion

            showversion(self)
        elif (
            getattr(self.option, "help", False) or "--help" in args or "-h" in args
        ):
            self._parser._getparser().print_help()
            sys.stdout.write(
                "\nNOTE: displaying only minimal help due to UsageError.\n\n"
            )

        raise

    return self

def _get_active_fixturedef(self, argname):
    try:
        return self._fixture_defs[argname]
    except KeyError:
        try:
            fixturedef = self._getnextfixturedef(argname)
        except FixtureLookupError:
            if argname == "request":
                cached_result = (self, [0], None)
                scope = "function"
                return PseudoFixtureDef(cached_result, scope)
            raise
    # remove indent to prevent the python3 exception
    # from leaking into the call
    self._compute_fixture_value(fixturedef)
    self._fixture_defs[argname] = fixturedef
    return fixturedef

def __init__(self, terminalwriter, *args, **kwargs):
    super(ColoredLevelFormatter, self).__init__(*args, **kwargs)
    if six.PY2:
        self._original_fmt = self._fmt
    else:
        self._original_fmt = self._style._fmt
    self._level_to_fmt_mapping = {}

    levelname_fmt_match = self.LEVELNAME_FMT_REGEX.search(self._fmt)
    if not levelname_fmt_match:
        return
    levelname_fmt = levelname_fmt_match.group()

    for level, color_opts in self.LOGLEVEL_COLOROPTS.items():
        formatted_levelname = levelname_fmt % {
            "levelname": logging.getLevelName(level)
        }

        # add ANSI escape sequences around the formatted levelname
        color_kwargs = {name: True for name in color_opts}
        colorized_formatted_levelname = terminalwriter.markup(
            formatted_levelname, **color_kwargs
        )
        self._level_to_fmt_mapping[level] = self.LEVELNAME_FMT_REGEX.sub(
            colorized_formatted_levelname, self._fmt
        )

def format(self, record):
    fmt = self._level_to_fmt_mapping.get(record.levelno, self._original_fmt)
    if six.PY2:
        self._fmt = fmt
    else:
        self._style._fmt = fmt
    return super(ColoredLevelFormatter, self).format(record)

def getini(self, name):
    """ return configuration value from an :ref:`ini file <inifiles>`. If the
    specified name hasn't been registered through a prior
    :py:func:`parser.addini <_pytest.config.Parser.addini>`
    call (usually from a plugin), a ValueError is raised. """
    try:
        return self._inicache[name]
    except KeyError:
        self._inicache[name] = val = self._getini(name)
        return val

def _getini(self, name):
    try:
        description, type, default = self._parser._inidict[name]
    except KeyError:
        raise ValueError("unknown configuration value: %r" % (name,))
    value = self._get_override_ini_value(name)
    if value is None:
        try:
            value = self.inicfg[name]
        except KeyError:
            if default is not None:
                return default
            if type is None:
                return ""
            return []
    if type == "pathlist":
        dp = py.path.local(self.inicfg.config.path).dirpath()
        values = []
        for relpath in shlex.split(value):
            values.append(dp.join(relpath, abs=True))
        return values
    elif type == "args":
        return shlex.split(value)
    elif type == "linelist":
        return [t for t in map(lambda x: x.strip(), value.split("\n")) if t]
    elif type == "bool":
        return bool(_strtobool(value.strip()))
    else:
        assert type is None
        return value

def _get_override_ini_value(self, name):
    value = None
    # override_ini is a list of "ini=value" options
    # always use the last item if multiple values are set for same ini-name,
    # e.g. -o foo=bar1 -o foo=bar2 will set foo to bar2
    for ini_config in self._override_ini:
        try:
            key, user_ini_value = ini_config.split("=", 1)
        except ValueError:
            raise UsageError("-o/--override-ini expects option=value style.")
        else:
            if key == name:
                value = user_ini_value
    return value

def _processopt(self, opt):
    for name in opt._short_opts + opt._long_opts:
        self._opt2dest[name] = opt.dest

    if hasattr(opt, "default") and opt.dest:
        if not hasattr(self.option, opt.dest):
            setattr(self.option, opt.dest, opt.default)

def repr_excinfo(self, excinfo):

    repr_chain = []
    e = excinfo.value
    descr = None
    seen = set()
    while e is not None and id(e) not in seen:
        seen.add(id(e))
        if excinfo:
            reprtraceback = self.repr_traceback(excinfo)
            reprcrash = excinfo._getreprcrash()
        else:
            # fallback to native repr if the exception doesn't have a traceback:
            # ExceptionInfo objects require a full traceback to work
            reprtraceback = ReprTracebackNative(
                traceback.format_exception(type(e), e, None)
            )
            reprcrash = None

        repr_chain += [(reprtraceback, reprcrash, descr)]
        if e.__cause__ is not None and self.chain:
            e = e.__cause__
            excinfo = (
                ExceptionInfo((type(e), e, e.__traceback__))
                if e.__traceback__
                else None
            )
            descr = "The above exception was the direct cause of the following exception:"
        elif (
            e.__context__ is not None and not e.__suppress_context__ and self.chain
        ):
            e = e.__context__
            excinfo = (
                ExceptionInfo((type(e), e, e.__traceback__))
                if e.__traceback__
                else None
            )
            descr = "During handling of the above exception, another exception occurred:"
        else:
            e = None
    repr_chain.reverse()
    return ExceptionChainRepr(repr_chain)

def repr_traceback(self, excinfo):
    traceback = excinfo.traceback
    if self.tbfilter:
        traceback = traceback.filter()

    if excinfo.errisinstance(RecursionError):
        traceback, extraline = self._truncate_recursive_traceback(traceback)
    else:
        extraline = None

    last = traceback[-1]
    entries = []
    for index, entry in enumerate(traceback):
        einfo = (last == entry) and excinfo or None
        reprentry = self.repr_traceback_entry(entry, einfo)
        entries.append(reprentry)
    return ReprTraceback(entries, extraline, style=self.style)

def _getentrysource(self, entry):
    source = entry.getsource(self.astcache)
    if source is not None:
        source = source.deindent()
    return source

def __str__(self):
    try:
        fn = str(self.path)
    except py.error.Error:
        fn = "???"
    name = self.frame.code.name
    try:
        line = str(self.statement).lstrip()
    except KeyboardInterrupt:
        raise
    except:  # noqa
        line = "???"
    return "  File %r:%d in %s\n  %s\n" % (fn, self.lineno + 1, name, line)

def _getreprcrash(self):
    exconly = self.exconly(tryshort=True)
    entry = self.traceback.getcrashentry()
    path, lineno = entry.frame.code.raw.co_filename, entry.lineno
    return ReprFileLocation(path, lineno + 1, exconly)

def getcrashentry(self):
    """ return last non-hidden traceback entry that lead
    to the exception of a traceback.
    """
    for i in range(-1, -len(self) - 1, -1):
        entry = self[i]
        if not entry.ishidden():
            return entry
    return self[-1]

def _validate(value, optdict, name=""):
    """Return a validated value for an option according to its type.

    optional argument name is only used for error message formatting
    """
    try:
        _type = optdict["type"]
    except KeyError:
        return value
    return _call_validator(_type, optdict, name, value)

def parse_pragma(pylint_pragma: str) -> Generator[PragmaRepresenter, None, None]:
    action: Optional[str] = None
    messages: List[str] = []
    assignment_required = False
    previous_token = ""

    for mo in re.finditer(TOK_REGEX, pylint_pragma):
        kind = mo.lastgroup
        value = mo.group()

        if kind == "ASSIGN":
            if not assignment_required:
                if action:
                    # A keyword has been found previously but doesn't support assignment
                    raise UnRecognizedOptionError(
                        "The keyword doesn't support assignment", action
                    )
                if previous_token:
                    # Something found previously but not a known keyword
                    raise UnRecognizedOptionError(
                        "The keyword is unknown", previous_token
                    )
                # Nothing at all detected before this assignment
                raise InvalidPragmaError("Missing keyword before assignment", "")
            assignment_required = False
        elif assignment_required:
            raise InvalidPragmaError(
                "The = sign is missing after the keyword", action or ""
            )
        elif kind == "KEYWORD":
            if action:
                yield emit_pragma_representer(action, messages)
            action = value
            messages = []
            assignment_required = action in MESSAGE_KEYWORDS
        elif kind in {"MESSAGE_STRING", "MESSAGE_NUMBER"}:
            messages.append(value)
            assignment_required = False
        else:
            raise RuntimeError("Token not recognized")

        previous_token = value

    if action:
        yield emit_pragma_representer(action, messages)
    else:
        raise UnRecognizedOptionError("The keyword is unknown", previous_token)

def preprocess_options(args, search_for):
    """Look for some options (keys of <search_for>) which have to be processed
    before others

    values of <search_for> are callback functions to call when the option is
    found
    """
    i = 0
    while i < len(args):
        arg = args[i]
        if not arg.startswith("--"):
            i += 1
        else:
            try:
                option, val = arg[2:].split("=", 1)
            except ValueError:
                option, val = arg[2:], None
            try:
                cb, takearg = search_for[option]
            except KeyError:
                i += 1
            else:
                del args[i]
                if takearg and val is None:
                    if i >= len(args) or args[i].startswith("-"):
                        msg = f"Option {option} expects a value"
                        raise ArgumentPreprocessingError(msg)
                    val = args[i]
                    del args[i]
                elif not takearg and val is not None:
                    msg = f"Option {option} doesn't expects a value"
                    raise ArgumentPreprocessingError(msg)
                cb(option, val)

def _non_empty_string_validator(opt, _, value):
    if not value:
        msg = "indent string can't be empty."
        raise optparse.OptionValueError(msg)
    return utils._unquote(value)

def _choice_validator(choices, name, value):
    if value not in choices:
        msg = "option %s: invalid value: %r, should be in %s"
        raise optparse.OptionValueError(msg % (name, value, choices))
    return value

def _check_initialpaths_for_relpath(session, fspath):
    for initial_path in session._initialpaths:
        if fspath.common(initial_path) == initial_path:
            return fspath.relto(initial_path)

def _node_location_to_relpath(self, node_path: py.path.local) -> str:
    # bestrelpath is a quite slow function
    return self._bestrelpathcache[node_path]

def resolve_from_str(input, root):
    assert not isinstance(input, Path), "would break on py2"
    root = Path(root)
    input = expanduser(input)
    input = expandvars(input)
    if isabs(input):
        return Path(input)
    else:
        return root.joinpath(input)

def get_fslocation_from_item(
    item: "Item",
) -> Tuple[Union[str, py.path.local], Optional[int]]:
    """Tries to extract the actual location from an item, depending on available attributes:

    * "fslocation": a pair (path, lineno)
    * "obj": a Python object that the item wraps.
    * "fspath": just a path

    :rtype: a tuple of (str|LocalPath, int) with filename and line number.
    """
    try:
        return item.location[:2]
    except AttributeError:
        pass
    obj = getattr(item, "obj", None)
    if obj is not None:
        return getfslineno(obj)
    return getattr(item, "fspath", "unknown location"), -1

def location(self) -> Tuple[str, Optional[int], str]:
    location = self.reportinfo()
    if isinstance(location[0], py.path.local):
        fspath = location[0]
    else:
        fspath = py.path.local(location[0])
    relfspath = self.session._node_location_to_relpath(fspath)
    assert type(location[2]) is str
    return (relfspath, location[1], location[2])

def _non_empty_string_transformer(value: str) -> str:
    """Check that a string is not empty and remove quotes."""
    if not value:
        raise argparse.ArgumentTypeError("Option cannot be an empty string.")
    return pylint_utils._unquote(value)

def _path_transformer(value: str) -> str:
    """Expand user and variables in a path."""
    return os.path.expandvars(os.path.expanduser(value))

def _py_version_transformer(value: str) -> tuple[int, ...]:
    """Transforms a version string into a version tuple."""
    try:
        version = tuple(int(val) for val in value.replace(",", ".").split("."))
    except ValueError:
        raise argparse.ArgumentTypeError(
            f"{value} has an invalid format, should be a version string. E.g., '3.8'"
        ) from None
    return version

def _parse_ini_file(self, file_path: Path) -> tuple[dict[str, str], list[str]]:
    """Parse and handle errors of a ini configuration file."""
    parser = configparser.ConfigParser(inline_comment_prefixes=("#", ";"))

    # Use this encoding in order to strip the BOM marker, if any.
    with open(file_path, encoding="utf_8_sig") as fp:
        parser.read_file(fp)

    config_content: dict[str, str] = {}
    options: list[str] = []
    for section in parser.sections():
        if self._ini_file_with_sections(file_path) and not section.startswith(
            "pylint"
        ):
            if section.lower() == "master":
                # TODO: 3.0: Remove deprecated handling of master, only allow 'pylint.' sections
                warnings.warn(
                    "The use of 'MASTER' or 'master' as configuration section for pylint "
                    "has been deprecated, as it's bad practice to not start sections titles with the "
                    "tool name. Please use 'pylint.main' instead.",
                    UserWarning,
                )
            else:
                continue
        for opt, value in parser[section].items():
            config_content[opt] = value
            options += [f"--{opt}", value]
    return config_content, options

def _ini_file_with_sections(file_path: Path) -> bool:
    """Return whether the file uses sections."""
    if "setup.cfg" in file_path.parts:
        return True
    if "tox.ini" in file_path.parts:
        return True
    return False

def _parse_toml_file(self, file_path: Path) -> tuple[dict[str, str], list[str]]:
    """Parse and handle errors of a toml configuration file."""
    try:
        with open(file_path, mode="rb") as fp:
            content = tomllib.load(fp)
    except tomllib.TOMLDecodeError as e:
        self.linter.add_message("config-parse-error", line=0, args=str(e))
        return {}, []

    try:
        sections_values = content["tool"]["pylint"]
    except KeyError:
        return {}, []

    config_content: dict[str, str] = {}
    options: list[str] = []
    for opt, values in sections_values.items():
        if isinstance(values, dict):
            for config, value in values.items():
                value = _parse_rich_type_value(value)
                config_content[config] = value
                options += [f"--{config}", value]
        else:
            values = _parse_rich_type_value(values)
            config_content[opt] = values
            options += [f"--{opt}", values]
    return config_content, options

def parse_config_file(
    self, file_path: Path | None
) -> tuple[dict[str, str], list[str]]:
    """Parse a config file and return str-str pairs."""
    if file_path is None:
        if self.verbose_mode:
            print(
                "No config file found, using default configuration", file=sys.stderr
            )
        return {}, []

    file_path = Path(os.path.expandvars(file_path)).expanduser()
    if not file_path.exists():
        raise OSError(f"The config file {file_path} doesn't exist!")

    if self.verbose_mode:
        print(f"Using config file {file_path}", file=sys.stderr)

    try:
        if file_path.suffix == ".toml":
            return self._parse_toml_file(file_path)
        return self._parse_ini_file(file_path)
    except (configparser.Error, tomllib.TOMLDecodeError) as e:
        self.linter.add_message("config-parse-error", line=0, args=str(e))
        return {}, []

def _load_default_argument_values(self) -> None:
    """Loads the default values of all registered options."""
    self.config = self._arg_parser.parse_args([], self.config)

def _add_arguments_to_parser(
    self, section: str, section_desc: str | None, argument: _Argument
) -> None:
    """Add an argument to the correct argument section/group."""
    try:
        section_group = self._argument_groups_dict[section]
    except KeyError:
        if section_desc:
            section_group = self._arg_parser.add_argument_group(
                section, section_desc
            )
        else:
            section_group = self._arg_parser.add_argument_group(title=section)
        self._argument_groups_dict[section] = section_group
    self._add_parser_option(section_group, argument)

def evaluate_condition(item: Item, mark: Mark, condition: object) -> Tuple[bool, str]:
    """Evaluate a single skipif/xfail condition.

    If an old-style string condition is given, it is eval()'d, otherwise the
    condition is bool()'d. If this fails, an appropriately formatted pytest.fail
    is raised.

    Returns (result, reason). The reason is only relevant if the result is True.
    """
    # String condition.
    if isinstance(condition, str):
        globals_ = {
            "os": os,
            "sys": sys,
            "platform": platform,
            "config": item.config,
        }
        for dictionary in reversed(
            item.ihook.pytest_markeval_namespace(config=item.config)
        ):
            if not isinstance(dictionary, Mapping):
                raise ValueError(
                    "pytest_markeval_namespace() needs to return a dict, got {!r}".format(
                        dictionary
                    )
                )
            globals_.update(dictionary)
        if hasattr(item, "obj"):
            globals_.update(item.obj.__globals__)  # type: ignore[attr-defined]
        try:
            filename = f"<{mark.name} condition>"
            condition_code = compile(condition, filename, "eval")
            result = eval(condition_code, globals_)
        except SyntaxError as exc:
            msglines = [
                "Error evaluating %r condition" % mark.name,
                "    " + condition,
                "    " + " " * (exc.offset or 0) + "^",
                "SyntaxError: invalid syntax",
            ]
            fail("\n".join(msglines), pytrace=False)
        except Exception as exc:
            msglines = [
                "Error evaluating %r condition" % mark.name,
                "    " + condition,
                *traceback.format_exception_only(type(exc), exc),
            ]
            fail("\n".join(msglines), pytrace=False)

    # Boolean condition.
    else:
        try:
            result = bool(condition)
        except Exception as exc:
            msglines = [
                "Error evaluating %r condition as a boolean" % mark.name,
                *traceback.format_exception_only(type(exc), exc),
            ]
            fail("\n".join(msglines), pytrace=False)

    reason = mark.kwargs.get("reason", None)
    if reason is None:
        if isinstance(condition, str):
            reason = "condition: " + condition
        else:
            # XXX better be checked at collection time
            msg = (
                "Error evaluating %r: " % mark.name
                + "you need to specify reason=STRING when using booleans as conditions."
            )
            fail(msg, pytrace=False)

    return result, reason

def pytest_pyfunc_call(pyfuncitem: "Function") -> Optional[object]:
    testfunction = pyfuncitem.obj
    if is_async_function(testfunction):
        async_warn_and_skip(pyfuncitem.nodeid)
    funcargs = pyfuncitem.funcargs
    testargs = {arg: funcargs[arg] for arg in pyfuncitem._fixtureinfo.argnames}
    result = testfunction(**testargs)
    if hasattr(result, "__await__") or hasattr(result, "__aiter__"):
        async_warn_and_skip(pyfuncitem.nodeid)
    return True

def pytest_collect_file(fspath: Path, parent: nodes.Collector) -> Optional["Module"]:
    if fspath.suffix == ".py":
        if not parent.session.isinitpath(fspath):
            if not path_matches_patterns(
                fspath, parent.config.getini("python_files") + ["__init__.py"]
            ):
                return None
        ihook = parent.session.gethookproxy(fspath)
        module: Module = ihook.pytest_pycollect_makemodule(fspath=fspath, parent=parent)
        return module
    return None

